import Foundation

/// 单条 settings 字典条目。数据＝官方 settings-reference 全表（2026-09-23 拉取，
/// cc-settings-reference-doc）231 键逐一对应；各字段＝官方中文原文（剥链接/反引号）。
struct ClaudeSettingEntry: Identifiable {
    let key: String          /// 顶层键或点路径（如 permissions.allow）
    let category: String     /// 官方 17 分类之一
    let desc: String
    let scope: String
    let type: String
    let defaultText: String
    let example: String      /// 官方撰写示例；空＝官方未给示例
    let exampleFile: String  /// 示例目标文件（settings.json / managed-settings.json…）

    var id: String { key }
}

/// Claude Code CLI settings 字典静态数据，按字母序排列，共 231 条 × 17 分类。
enum ClaudeSettingsDict {
    static let entries: [ClaudeSettingEntry] = [
        ClaudeSettingEntry(key: "advisorModel", category: "模型和响应", desc: "选择当 Claude 调用服务器端顾问工具时哪个模型来回答。取消设置它以关闭顾问。顾问的能力必须至少与您的主模型一样强。请参阅选择顾问模型了解接受的配对以及选择未被接受的配对时会发生什么。 您通常不会手动编辑此键。运行 /advisor 打开一个选择器，显示当前选择、可以提供建议的模型和**无顾问**。Claude Code 将您的选择保存到 ~/.claude/settings.json 中的此键。如果您从远程控制客户端或附加到远程工作者的会话中选择，该选择仅适用于该会话，不会更改此键。 如果您的账户需要使用额度同意，请先通过运行 /model fable 来接受。在您这样做之前，在 /advisor 中选择 Fable 不会保存任何内容，Claude Code 会告诉您先运行 /model fable。", scope: "Any file", type: "string，别名之一 \"fable\"、\"opus\" 或 \"sonnet\"，它们解析为 Claude Code 当前该模型系列的默认版本，或完整模型 ID，如 \"claude-opus-5-5\"", defaultText: "未设置，因此顾问已关闭", example: "{\n  \"advisorModel\": \"opus\"\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "agent", category: "代理、会话和工作树", desc: "将主线程作为命名的 subagent 运行，以便 Claude Code 将该 subagent 的系统提示、工具限制和模型应用于您的会话。同一密钥为从 claude agents 分派的会话设置默认代理。", scope: "Any file", type: "string，内置或自定义代理的名称", defaultText: "未设置，因此主线程作为 Claude Code 的默认代理运行", example: "{\n  \"agent\": \"code-reviewer\"\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "agentPushNotifEnabled", category: "远程、桌面和通知", desc: "允许 Claude 在认为值得发送时向你的手机发送推送通知，例如当长任务完成时。Claude Code 将此选择同步到你的账户，推送在远程控制连接时到达。在 /config 中显示为**Claude 决定时推送**。", scope: "任何文件。Claude Code 也会读取由旧版本留在 ~/.claude.json 中的值。", type: "布尔值", defaultText: "false", example: "{\n  \"agentPushNotifEnabled\": true\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "allowAllClaudeAiMcps", category: "MCP", desc: "加载 claude.ai 连接器，Claude Code 会在部署的 managed-mcp.json 旁边自行获取这些连接器。如果没有此密钥，managed-mcp.json 将对 MCP 服务器拥有独占控制权并禁止这些连接器。", scope: "Managed。用户无法重新启用独占控制禁止的连接器。", type: "布尔值", defaultText: "false，因此部署的 managed-mcp.json 会禁止 Claude Code 自行获取的 claude.ai 连接器", example: "{\n  \"allowAllClaudeAiMcps\": true\n}", exampleFile: "managed-settings.json"),
        ClaudeSettingEntry(key: "allowManagedHooksOnly", category: "Hooks 和自动化", desc: "限制 hook 执行仅限于您的组织部署的 hooks。", scope: "托管", type: "布尔值", defaultText: "未设置，因此来自每个设置作用域和插件的 hooks 都运行", example: "{\n  \"allowManagedHooksOnly\": true\n}", exampleFile: "managed-settings.json"),
        ClaudeSettingEntry(key: "allowManagedMcpServersOnly", category: "MCP", desc: "使托管允许列表成为唯一适用的列表。Claude Code 随后仅从托管设置中读取 allowedMcpServers，并忽略用户、项目和本地设置中的允许列表；deniedMcpServers 仍然从每个设置作用域合并，因此用户仍然可以为自己阻止服务器。管理员设置它，以便用户自己的设置无法扩展托管允许列表允许的内容。", scope: "Managed", type: "布尔值", defaultText: "false，因此来自每个设置作用域的允许列表合并", example: "{\n  \"allowManagedMcpServersOnly\": true,\n  \"allowedMcpServers\": [\n    { \"serverName\": \"github\" }\n  ]\n}", exampleFile: "managed-settings.json"),
        ClaudeSettingEntry(key: "allowManagedPermissionRulesOnly", category: "权限设置", desc: "使托管设置成为权限规则的唯一设置源。Claude Code 随后会忽略用户、项目、本地和 --settings 文件中的 allow、ask 和 deny 规则，忽略 --allowedTools，隐藏权限提示中的始终允许选项，并停止保存新规则。 当来自嵌入主机的父设置适用时，Claude Code 将其视为托管层的一部分。它删除其 allow 规则和 additionalDirectories，并保留其 deny 和 ask 规则，除了 Read 和 Edit 规则，其模式以 ! 开头。主机无法使用 ! 规则从托管规则中切割出路径，无论您是否设置此键。 --disallowedTools 规则和当前会话的 deny 和 ask 规则仍然适用，包括在 Claude Code 在会话中途重新加载设置后。它们仅限制，因此无法扩展托管规则授予的权限。在 v2.1.257 之前，Claude Code 在第一次设置重新加载时删除了这些命令行和会话规则。 有关 ! 模式在 --disallowedTools 或会话规则中可以切割出什么，请参阅Read 和 Edit 规则。", scope: "Managed", type: "布尔值", defaultText: "未设置，因此 Claude Code 应用来自用户、项目和本地设置以及 --settings 的权限规则，以及托管规则", example: "{\n  \"allowManagedPermissionRulesOnly\": true\n}", exampleFile: "managed-settings.json"),
        ClaudeSettingEntry(key: "allowedChannelPlugins", category: "插件和技能", desc: "选择哪些 channel 插件可以将消息推送到您组织中的会话。设置后，Claude Code 使用您的列表代替默认的 Anthropic 允许列表；每个条目命名一个插件及其来自的市场。", scope: "Managed", type: "对象数组，每个对象都有 marketplace 和 plugin 字符串。条目也可以是 \"plugin@marketplace\" 字符串，如 \"telegram@claude-plugins-official\"，Claude Code 将其视为等效对象。字符串形式需要 Claude Code v2.1.267 或更高版本；较早版本在包含一个时拒绝整个 allowedChannelPlugins 值", defaultText: "未设置，因此 Claude Code 使用默认的 Anthropic 允许列表", example: "{\n  \"channelsEnabled\": true,\n  \"allowedChannelPlugins\": [\n    { \"marketplace\": \"claude-plugins-official\", \"plugin\": \"telegram\" }\n  ]\n}", exampleFile: "managed-settings.json"),
        ClaudeSettingEntry(key: "allowedHttpHookUrls", category: "Hooks 和自动化", desc: "限制 HTTP hooks 可以针对的 URL。定义此键时，Claude Code 仅在 HTTP hook 的 URL 与某个模式匹配时才运行该 hook，并阻止其余的而不运行它们；空数组会阻止每个 HTTP hook。", scope: "任何文件。数组在设置文件中合并。", type: "URL 模式数组，* 作为通配符", defaultText: "未设置，因此允许任何 URL", example: "{\n  \"allowedHttpHookUrls\": [\"https://hooks.example.com/*\", \"http://localhost:*\"]\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "allowedMcpServers", category: "MCP", desc: "允许列表化人们可以添加的 MCP 服务器。Claude Code 会阻止任何不匹配条目的服务器，无论在何处定义，包括插件服务器、使用 --mcp-config 传递的服务器以及来自 claude.ai 的服务器。 内置服务器（例如 Chrome 中的 Claude、Claude Code 在运行的 VS Code 或 JetBrains IDE 中连接的 ide 服务器，以及 CLI 本身配置的服务器）不受允许列表的限制，拒绝列表仍然适用于它们。进程内 type: \"sdk\" 服务器不受两个列表的限制；启动会话的应用会注册它们。 您的组织提供的服务器也不受允许列表的限制，拒绝列表仍然适用于它们。豁免涵盖每个 managedMcpServers 条目，以及任何 managed-mcp.json 条目，其值不使用 ${VAR} 扩展。有关完整的检查顺序，请参阅如何评估服务器。在 v2.1.259 之前，来自 managed-mcp.json 的服务器也必须匹配。", scope: "Any file。来自每个文件的条目合并为一个允许列表，除非设置了 allowManagedMcpServersOnly。在托管设置中部署它以强制执行。", type: "对象数组，每个对象恰好有一个密钥：serverName，一个限制为字母、数字、连字符和下划线的字符串；serverCommand，一个与命令及其参数完全匹配的数组；或 serverUrl，一个带有 * 通配符的 URL 模式", defaultText: "未设置，因此允许每个服务器；空数组会阻止用户添加的每个服务器", example: "{\n  \"allowedMcpServers\": [\n    { \"serverCommand\": [\"npx\", \"-y\", \"@modelcontextprotocol/server-filesystem\"] }\n  ]\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "alwaysThinkingEnabled", category: "模型和响应", desc: "通过将其设置为 false 来为每个会话关闭扩展思考。默认情况下思考是打开的，所以 true 不会改变任何内容。大多数人通过 /config 而不是编辑文件来设置这个。 在始终思考的模型上，例如 Opus 5.5 和 Fable 模型，false 没有效果。在第三方提供商上，Claude Code 省略 thinking 参数而不是关闭思考，因此自适应推理模型可能仍然会思考。在 Anthropic API 上关闭思考时，Claude Code 向它知道不接受该组合的模型（例如 Opus 5）发送努力 high 而不是更高级别。", scope: "Any file", type: "Boolean", defaultText: "未设置，因此对支持它的模型思考是打开的", example: "{\n  \"alwaysThinkingEnabled\": false\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "apiKeyHelper", category: "身份验证和提供商", desc: "运行您自己的命令来生成 Claude Code 随模型请求发送的凭证。Claude Code 通过系统 shell 运行该命令，在 macOS 和 Linux 上为 /bin/sh，在 Windows 上为 cmd，并将其输出作为 X-Api-Key 和 Authorization: Bearer 标头发送。将其用于动态或轮换凭证，例如从保管库获取的短期令牌。", scope: "Any file", type: "string，shell 命令行", defaultText: "未设置，因此 Claude Code 不运行辅助程序", example: "{\n  \"apiKeyHelper\": \"/bin/generate_temp_api_key.sh\"\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "askUserQuestionTimeout", category: "界面和终端", desc: "让未回答的 AskUserQuestion 对话框在空闲一段时间后自动继续，提交您已选择的任何选项。当您离开时设置此项，让 Claude 在没有您的情况下继续。使用默认设置时，问题会等待您回答。需要 Claude Code v2.1.200 或更高版本。", scope: "User or managed", type: "string，值为 \"60s\"、\"5m\"、\"10m\" 或 \"never\" 之一", defaultText: "\"never\"", example: "{\n  \"askUserQuestionTimeout\": \"5m\"\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "attribution", category: "Git 和归属", desc: "自定义 Claude Code 添加到 git 提交和拉取请求的归属。提交默认获得 git trailer，例如 Co-Authored-By；拉取请求描述获得纯文本。使用下面的子键分别设置每个部分。", scope: "Any file", type: "包含 commit 和 pr 字符串以及 sessionUrl 布尔值的对象", defaultText: "未设置，因此 Claude Code 使用每个子键下显示的标准归属", example: "{\n  \"attribution\": {\n    \"commit\": \"Generated with AI\\n\\nCo-Authored-By: AI <ai@example.com>\",\n    \"pr\": \"\",\n    \"sessionUrl\": false\n  }\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "attribution.commit", category: "Git 和归属", desc: "设置 Claude Code 添加到 git 提交的归属文本，包括任何 trailer。将其设置为空字符串以隐藏提交归属。", scope: "Any file", type: "字符串", defaultText: "未设置，因此 Claude Code 添加 Co-Authored-By: <name> <noreply@anthropic.com>。名称是会话的活跃模型，例如 Claude Sonnet 5。", example: "{\n  \"attribution\": {\n    \"commit\": \"Generated with AI\\n\\nCo-Authored-By: AI <ai@example.com>\"\n  }\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "attribution.pr", category: "Git 和归属", desc: "设置 Claude Code 添加到拉取请求描述的归属文本。将其设置为空字符串以隐藏拉取请求归属。", scope: "Any file", type: "字符串", defaultText: "未设置，因此 Claude Code 添加 🤖 Generated with Claude Code", example: "{\n  \"attribution\": {\n    \"pr\": \"\"\n  }\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "attribution.sessionUrl", category: "Git 和归属", desc: "选择 Claude Code 在从 cloud 或 Remote Control 会话提交或打开拉取请求时是否附加 claude.ai 会话链接。Claude Code 在提交上添加链接作为 Claude-Session trailer，在拉取请求描述中添加链接。将其设置为 false 以省略链接。", scope: "Any file", type: "布尔值", defaultText: "true", example: "{\n  \"attribution\": {\n    \"sessionUrl\": false\n  }\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "autoCompactEnabled", category: "内存和上下文", desc: "当上下文接近限制时，让 Claude Code 自动压缩对话。在 /config 中显示为**自动压缩**，在那里切换它会将此键写入您的用户设置。", scope: "Any file", type: "Boolean", defaultText: "true", example: "{\n  \"autoCompactEnabled\": false\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "autoCompactWindow", category: "内存和上下文", desc: "设置在 Claude Code 自动压缩之前上下文窗口的填充程度。", scope: "Any file", type: "令牌数，从 100000 到 1000000。Claude Code 将值限制在您的模型的上下文窗口；模型概览列出了每个模型的窗口", defaultText: "未设置，因此 Claude Code 选择为您的模型调整的窗口", example: "{\n  \"autoCompactWindow\": 500000\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "autoConnectIde", category: "全局配置设置", desc: "当你从外部终端启动 Claude Code 时，自动连接到正在运行的 IDE。当你在 VS Code 或 JetBrains 终端外运行 Claude Code 时，在 /config 中显示为**自动连接到 IDE（外部终端）**。", scope: "全局配置", type: "布尔值", defaultText: "false", example: "{\n  \"autoConnectIde\": true\n}", exampleFile: "~/.claude.json"),
        ClaudeSettingEntry(key: "autoContinueAtUsageLimit", category: "界面和终端", desc: "在 claude.ai 使用限制停止您的会话后，在打开的会话中等待，并在重置后自动继续任务。请参阅关闭自动继续。需要 Claude Code v2.1.234 或更高版本。", scope: "User or managed。仅从用户设置、--settings 和托管设置中读取。当这些都没有设置此键时，设置此键的项目或本地设置文件会关闭该功能，而不是被忽略。", type: "Boolean", defaultText: "true", example: "{\n  \"autoContinueAtUsageLimit\": false\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "autoInstallIdeExtension", category: "全局配置设置", desc: "当你从 VS Code 终端运行 Claude Code 时，自动安装 Claude Code IDE 扩展。当你在 VS Code 或 JetBrains 终端内运行 Claude Code 时，在 /config 中显示为**自动安装 IDE 扩展**。", scope: "全局配置", type: "布尔值", defaultText: "true", example: "{\n  \"autoInstallIdeExtension\": false\n}", exampleFile: "~/.claude.json"),
        ClaudeSettingEntry(key: "autoMemoryDirectory", category: "内存和上下文", desc: "将自动内存存储在您选择的目录中，而不是每个项目的默认值。", scope: "Any file", type: "字符串，绝对路径或 ~/ 前缀的目录路径", defaultText: "未设置，因此 Claude Code 使用 ~/.claude/projects/<project>/memory/", example: "{\n  \"autoMemoryDirectory\": \"~/my-memory-dir\"\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "autoMemoryEnabled", category: "内存和上下文", desc: "打开或关闭自动内存。当为 false 时，Claude 不会从自动内存目录读取或写入。您也可以在会话期间使用 /memory 切换它，这会将此键写入您的用户设置。", scope: "Any file", type: "Boolean", defaultText: "true", example: "{\n  \"autoMemoryEnabled\": false\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "autoMode", category: "权限设置", desc: "向自动模式分类器阻止和允许的内容添加您自己的规则。使用它告诉分类器您的组织信任哪些存储库、存储桶和域，以便它停止阻止常规内部操作。分类器附带内置允许和拒绝规则。在数组中包含字面字符串 \"$defaults\" 以在该位置保留这些内置规则并在其周围添加您的规则；省略它以用您的规则替换它们。", scope: "User or managed", type: "包含 environment、allow、soft_deny 和 hard_deny 散文规则数组的对象，加上 classifyAllShell 布尔值", defaultText: "未设置，因此分类器仅使用其内置规则", example: "{\n  \"autoMode\": {\n    \"soft_deny\": [\"$defaults\", \"Never run terraform apply\"]\n  }\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "autoMode.classifyAllShell", category: "权限设置", desc: "在自动模式处于活动状态时，通过自动模式分类器发送每个 Bash 和 PowerShell 命令。默认情况下，自动模式仅暂停可能运行任意代码的允许规则：工具范围和通配符规则（如 Bash(*)）以及解释器或 shell 包装器前缀（如 Bash(python *)）。任何其他允许规则匹配的命令（如 Bash(npm test)）会跳过分类器，除非它携带每命令允许的域，规则的前缀未预期的破坏性参数可能会被看不见地通过。设置此键会为会话暂停每个 shell 允许规则，以便分类器看到每个命令。需要 Claude Code v2.1.193 或更高版本。", scope: "User or managed。在读取 autoMode 的任何地方读取。", type: "布尔值", defaultText: "false", example: "{\n  \"autoMode\": {\n    \"classifyAllShell\": true\n  }\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "autoScrollEnabled", category: "界面和终端", desc: "在全屏渲染中跟随新输出到对话底部。关闭它以在 Claude 继续工作时保持您滚动的位置；权限提示仍会滚动到视图中。", scope: "Any file", type: "Boolean", defaultText: "true", example: "{\n  \"autoScrollEnabled\": false\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "autoUpdatesChannel", category: "更新和版本控制", desc: "选择发布渠道，背景自动更新和 claude update 遵循该渠道。设置 \"stable\" 以获得通常约一周前的版本，并跳过有重大回归的发布，或设置 \"latest\" 以获得最新发布。", scope: "Any file。在托管设置中设置以在整个组织中强制执行一个渠道。", type: "string，以下之一：", defaultText: "未设置，所以 Claude Code 遵循 \"latest\"", example: "{\n  \"autoUpdatesChannel\": \"stable\"\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "availableModels", category: "模型和响应", desc: "限制人们可以为主会话、子代理、skills 和顾问选择的模型。托管列表限制 /model、--model 和开发人员自己文件中的 model 键；列表外的模型无法选择。单独来说，这不会触及默认选项；将其与enforceAvailableModels配对以实现该目的。", scope: "Any file。在托管设置中部署它以为组织强制执行。", type: "模型别名或 ID 的数组", defaultText: "未设置，因此每个模型都可用", example: "{\n  \"availableModels\": [\"sonnet\", \"haiku\"]\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "awaySummaryEnabled", category: "远程、桌面和通知", desc: "当你离开终端几分钟后返回时，显示一行会话摘要。将其设置为 false，或在 /config 中关闭**会话摘要**，以停止摘要。", scope: "任何文件", type: "布尔值", defaultText: "未设置，因此摘要处于开启状态", example: "{\n  \"awaySummaryEnabled\": false\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "awsAuthRefresh", category: "身份验证和提供商", desc: "运行您自己的命令（例如 aws sso login），以在 Claude Code 用于 Amazon Bedrock 的凭证停止工作时刷新 .aws 目录中的凭证。Claude Code 首先根据 STS 检查当前凭证，仅在该检查失败时运行该命令，然后读取刷新的 .aws 目录。", scope: "Any file", type: "string，shell 命令行", defaultText: "未设置，因此 Claude Code 不为您刷新 AWS 凭证", example: "{\n  \"awsAuthRefresh\": \"aws sso login --profile myprofile\"\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "awsCredentialExport", category: "身份验证和提供商", desc: "运行您自己的命令，该命令将 AWS 凭证打印为 JSON，以便 Claude Code 可以使用不存在于 .aws 目录中的凭证调用 Amazon Bedrock。Claude Code 接受 aws sts 输出形状和平面 aws configure export-credentials 形状，并将凭证范围限定为其自己的 Bedrock 客户端，因此 Claude Code 运行的 shell 命令仍然看到您的环境凭证。", scope: "Any file", type: "string，shell 命令行", defaultText: "未设置，因此 Claude Code 使用环境 AWS 凭证链", example: "{\n  \"awsCredentialExport\": \"/bin/generate_aws_grant.sh\"\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "axScreenReader", category: "界面和终端", desc: "渲染屏幕阅读器友好的输出：没有装饰性边框或动画的平面文本。屏幕阅读器模式使用经典渲染器，因此在它处于活动状态时 tui 设置无效；附加的后台会话仍会全屏渲染。", scope: "Any file", type: "Boolean", defaultText: "unset，所以屏幕阅读器模式关闭", example: "{\n  \"axScreenReader\": true\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "bashEditDiffEnabled", category: "界面和终端", desc: "选择 Claude Code 是否记录 Bash 命令在 Git 存储库中更改的文件。当它记录它们时，您会在命令后在终端中看到它们的差异，您的 PostToolUse Bash hooks 会接收更改的文件列表。 列出的文件并不总是命令更改的文件。命令运行时另一个程序或另一个 Bash 调用所做的更改也可能出现在那里。 将键设置为 true 以在每个权限模式中记录它们。需要 Claude Code v2.1.269 或更高版本。", scope: "User or managed。true 仅从您的用户设置、使用 --settings 传递的 JSON 或托管设置计数，因此存储库的 .claude/settings.json 或 .claude/settings.local.json 中的 true 无法打开记录。存储库文件中的 false 仍会关闭它，除非更高优先级的文件设置 true。", type: "Boolean", defaultText: "unset，所以当 Claude Code 指导 Claude 通过 Bash 编辑文件时，Claude Code 在自动模式和 bypassPermissions 模式中记录更改", example: "{\n  \"bashEditDiffEnabled\": true\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "bashOutputMaxChars", category: "内存和上下文", desc: "设置成功的 Bash 或 PowerShell 命令的输出 Claude 内联接收的字符数。当输出超过限制时，Claude Code 将其保存到文件，Claude 接收简短预览加文件路径。当命令输出（例如详细构建或完整测试套件日志）经常超过默认值且您希望 Claude 在不打开文件的情况下读取它时，提高限制。需要 Claude Code v2.1.261 或更高版本。", scope: "Any file", type: "字符数，正整数。Claude Code 将值限制在 4000 到 128000 范围内", defaultText: "未设置，因此 Claude 内联接收最多 30,000 个字符", example: "{\n  \"bashOutputMaxChars\": 100000\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "blockedMarketplaces", category: "插件和技能", desc: "为您的组织阻止插件市场来源。Claude Code 在市场添加以及插件安装、更新、刷新和自动更新时检查阻止列表，因此在您设置策略之前添加的市场无法用于获取插件。在下载前检查被阻止的来源，因此它们永远不会接触文件系统。", scope: "Managed", type: "市场来源对象数组，形式与 strictKnownMarketplaces 相同", defaultText: "未设置，因此没有市场被阻止", example: "{\n  \"blockedMarketplaces\": [\n    { \"source\": \"github\", \"repo\": \"untrusted/plugins\" }\n  ]\n}", exampleFile: "managed-settings.json"),
        ClaudeSettingEntry(key: "browserExternalPageTools", category: "Tools", desc: "阻止 Claude 在桌面应用的 浏览器窗格 中使用其工具读取或作用于外部页面。您组织中的人员仍然可以自己打开外部网站，本地开发服务器预览继续与 Claude 的工具一起工作。桌面应用读取此密钥；终端 CLI 会忽略它。", scope: "Managed", type: "string，\"disabled\"；桌面应用也接受 \"disable\"，在任何一种情况下", defaultText: "未设置，因此 Claude 的工具可在外部页面上工作", example: "{\n  \"browserExternalPageTools\": \"disabled\"\n}", exampleFile: "managed-settings.json"),
        ClaudeSettingEntry(key: "channelsEnabled", category: "插件和技能", desc: "为您的组织允许 channels。在 claude.ai Team 和 Enterprise 计划上，Claude Code 阻止频道，直到您将其设置为 true。对于使用 API 密钥进行身份验证的 Anthropic Console 帐户，默认允许频道。如果您的组织部署托管设置，Claude Code 也会在这些帐户上阻止频道，直到您将此键设置为 true。", scope: "Managed", type: "Boolean", defaultText: "未设置；频道在 Team 和 Enterprise 计划以及具有托管设置的 Console 帐户上被阻止，在 Pro 和 Max 计划以及没有托管设置的 Console 帐户上被允许", example: "{\n  \"channelsEnabled\": true\n}", exampleFile: "managed-settings.json"),
        ClaudeSettingEntry(key: "claudeMd", category: "内存和上下文", desc: "注入 CLAUDE.md 风格的说明作为组织管理的内存，无需部署单独的文件。Claude Code 将文本作为托管内存条目加载，位于用户和项目 CLAUDE.md 文件之前。", scope: "Managed", type: "字符串，CLAUDE.md 文件的文本；按照您编写文件的方式编写，包括 Markdown，行中断为 \\n", defaultText: "未设置", example: "{\n  \"claudeMd\": \"# Engineering rules\\n\\n- Always run make lint before committing.\\n- Never push directly to main.\"\n}", exampleFile: "managed-settings.json"),
        ClaudeSettingEntry(key: "claudeMdExcludes", category: "内存和上下文", desc: "当 Claude Code 加载内存时跳过特定的 CLAUDE.md 文件。在大型单体仓库中，使用它跳过来自与您的工作无关的其他团队的 CLAUDE.md 文件；大型代码库指南中的排除无关的 CLAUDE.md 文件演示了该情况。模式与绝对文件路径匹配。", scope: "Any file", type: "字符串数组，每个都是 glob 模式或绝对路径", defaultText: "未设置，因此 Claude Code 加载它找到的每个 CLAUDE.md", example: "{\n  \"claudeMdExcludes\": [\"**/vendor/**/CLAUDE.md\"]\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "cleanupPeriodDays", category: "隐私和遥测", desc: "设置 Claude Code 在删除之前保留会话记录和其他应用程序数据的天数。Claude Code 在会话开始后作为后台扫描运行删除，只要它能够安全地确定保留期。", scope: "任何文件", type: "天数，整数，最小值 1", defaultText: "30", example: "{\n  \"cleanupPeriodDays\": 20\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "companyAnnouncements", category: "界面和终端", desc: "在启动时向用户显示您组织的公告。当您列出多个公告时，Claude Code 为每个会话随机选择一个；在某人的首次启动时，它显示第一个条目。", scope: "Any file", type: "array of strings", defaultText: "unset，所以不显示公告", example: "{\n  \"companyAnnouncements\": [\n    \"欢迎来到 Acme Corp！请在 docs.example.com 查看我们的代码指南\"\n  ]\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "copyOnSelect", category: "全局配置设置", desc: "当你在全屏渲染或代理视图中用鼠标完成文本选择时，自动将文本复制到剪贴板。在全屏渲染打开时，在 /config 中显示为**选择时复制**。", scope: "全局配置", type: "布尔值", defaultText: "true", example: "{\n  \"copyOnSelect\": false\n}", exampleFile: "~/.claude.json"),
        ClaudeSettingEntry(key: "crossSessionInbound", category: "代理、会话和工作树", desc: "选择此会话如何处理 来自您其他 Claude Code 会话的消息。当没有值适用时，Claude Code 根据两个会话的权限模式类从每条消息中决定。需要 Claude Code v2.1.224 或更高版本。", scope: "Any file。项目或本地值仅在严格于托管设置、--settings 标志或用户设置提供的值时才适用。", type: "string，以下之一：", defaultText: "未设置，因此 Claude Code 从每条消息中决定", example: "{\n  \"crossSessionInbound\": \"hold\"\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "defaultShell", category: "界面和终端", desc: "选择 Bash 或 PowerShell 是否运行您在输入框中使用 ! 前缀键入的 shell 命令，以及 Claude Code 直接运行并添加到会话的命令。 \"powershell\" 仅在 PowerShell tool 打开时有效。该工具在没有 Git Bash 的 Windows 上默认打开，在带有 Git Bash 的 Windows 上对于 claude.ai 和 Console 账户默认打开。在 Amazon Bedrock、Google Cloud 的 Agent Platform 和 Microsoft Foundry 会话中，以及在 macOS、Linux 和 WSL 上，设置 CLAUDE_CODE_USE_POWERSHELL_TOOL=1 以打开该工具。将该变量设置为 0 以关闭该工具。", scope: "Any file", type: "string，值为以下之一：", defaultText: "\"bash\"，或在 Bash 不可用时在 Windows 上为 \"powershell\"", example: "{\n  \"defaultShell\": \"powershell\"\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "deniedMcpServers", category: "MCP", desc: "阻止特定的 MCP 服务器。Claude Code 拒绝加载匹配的服务器，无论在何处定义，包括插件服务器、使用 --mcp-config 传递的服务器、来自 managed-mcp.json 的服务器、来自 managedMcpServers 的服务器，以及 它自行获取的 claude.ai 连接器。进程内 type: \"sdk\" 服务器不受限制；启动会话的应用会注册它们。", scope: "Any file。来自每个文件的条目合并为一个拒绝列表，allowManagedMcpServersOnly 不会改变这一点。在托管设置中部署它以强制执行。", type: "对象数组，每个对象恰好有一个密钥：serverName，一个字符串，因此 claude.ai 连接器的显示名称（例如 \"claude.ai Slack\"）有效；serverCommand，一个与命令及其参数完全匹配的数组；或 serverUrl，一个带有 * 通配符的 URL 模式", defaultText: "未设置，因此不阻止任何服务器；空数组也不阻止任何内容", example: "{\n  \"deniedMcpServers\": [\n    { \"serverName\": \"filesystem\" }\n  ]\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "desktopSessionCleanupPeriodDays", category: "隐私和遥测", desc: "为您在 Claude Desktop 或 Cowork 中启动或最近继续的会话的记录设置天数年龄限制。没有此键，Claude Code 会无限期地保留这些记录。Claude Code 在每个记录的年龄超过此限制和 cleanupPeriodDays 时删除它，因此当 cleanupPeriodDays 处于其默认值 30 时，值 7 仍会保留它们 30 天。当托管设置设置 cleanupPeriodDays 时，该期间改为适用，此键被忽略。需要 Claude Code v2.1.248 或更高版本。", scope: "用户或托管。Claude Code 也从您使用 --settings 传递的文件中读取该键，并在项目和本地设置中忽略它。", type: "天数，整数，最小值 0", defaultText: "0，不设置年龄限制", example: "{\n  \"desktopSessionCleanupPeriodDays\": 90\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "dialogExpiry", category: "界面和终端", desc: "为 Claude Code 转发给远程客户端的对话框（例如远程控制或 SDK 主机）以及保留的跨会话消息的批准对话框设置截止时间。在 Claude Code v2.1.236 或更高版本上，相同的截止时间限制了会话中可能没有人在终端的中期 Fable 使用额度同意提示。当在截止时间前没有答案到达时，Claude Code 取消对话框并继续使用其无操作默认值。需要 Claude Code v2.1.224 或更高版本。", scope: "User or managed", type: "string，值为 \"60s\"、\"5m\"、\"10m\" 或 \"never\" 之一，后者禁用截止时间", defaultText: "\"5m\"", example: "{\n  \"dialogExpiry\": \"10m\"\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "diffTool", category: "全局配置设置", desc: "选择 Claude Code 在连接VS Code或JetBrains IDE 时显示其提议的 Edit 或 Write 更改的 diff 的位置：\"auto\" 在 IDE 的 diff 查看器中打开它，\"terminal\" 将其保留在终端中。仅当 Claude Code 连接到 VS Code 或 JetBrains IDE 时，在 /config 中显示为**Diff 工具**。", scope: "全局配置", type: "字符串，以下之一：", defaultText: "\"auto\"", example: "{\n  \"diffTool\": \"terminal\"\n}", exampleFile: "~/.claude.json"),
        ClaudeSettingEntry(key: "disableAgentView", category: "代理、会话和工作树", desc: "关闭 background agents and agent view：claude agents、--bg、/background 和按需主管。在 managed settings 中设置它以为组织强制执行。", scope: "Any file", type: "Boolean", defaultText: "未设置，因此 agent view 可用", example: "{\n  \"disableAgentView\": true\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "disableAllHooks", category: "Hooks 和自动化", desc: "关闭 hooks、任何自定义 状态行 和任何自定义 文件建议 命令。使用它可以临时关闭所有这些，而无需从设置中删除它们。", scope: "任何文件。仅托管设置可以禁用托管 hooks。", type: "布尔值", defaultText: "未设置，因此 hooks 运行", example: "{\n  \"disableAllHooks\": true\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "disableArtifact", category: "远程、桌面和通知", desc: "<Warning> 已弃用，已被 enableArtifact 替代。Claude Code 仍然将 disableArtifact: true 视为等同于 enableArtifact: false，并忽略 disableArtifact: false。 </Warning> 改用 enableArtifact 来关闭 Artifact 工具，该工具将会话输出发布为 claude.ai 上的私有网页。当你在 /config 中关闭**Artifacts** 行时，Claude Code 会将 enableArtifact 写入你的用户设置并清除此键。", scope: "任何文件", type: "布尔值", defaultText: "未设置，因此工具遵循你账户的可用性", example: "{\n  \"disableArtifact\": true\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "disableAutoMode", category: "权限设置", desc: "从 Shift+Tab 循环中删除自动模式。任何本应以自动模式启动的会话，无论是来自 --permission-mode auto、设置文件还是内置默认值，都会改为以 default 启动。管理员在托管设置中设置它以防止其组织中的开发人员使用自动模式。", scope: "Any file。在托管设置中最有用，用户无法覆盖它。也接受在 permissions 下作为 permissions.disableAutoMode。", type: "字符串 \"disable\"", defaultText: "未设置", example: "{\n  \"disableAutoMode\": \"disable\"\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "disableBrowserExternalNavigation", category: "Tools", desc: "在桌面应用的 浏览器窗格 中为人员和 Claude 关闭外部浏览。Localhost 开发服务器预览继续工作。桌面应用读取此密钥；终端 CLI 会忽略它。", scope: "Managed", type: "Boolean；仅 JSON Boolean true 生效", defaultText: "未设置，因此外部浏览是打开的", example: "{\n  \"disableBrowserExternalNavigation\": true\n}", exampleFile: "managed-settings.json"),
        ClaudeSettingEntry(key: "disableBundledSkills", category: "插件和技能", desc: "关闭 Claude Code 附带的 skills 和工作流。Claude Code 完全删除捆绑的技能和工作流，而内置命令（如 /init）仍可输入但对模型隐藏。", scope: "Any file", type: "Boolean", defaultText: "未设置，因此捆绑的技能加载", example: "{\n  \"disableBundledSkills\": true\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "disableClaudeAiConnectors", category: "MCP", desc: "关闭 claude.ai MCP 连接器 Claude Code 自行获取，因此它既不获取也不连接它们。任何设置文件中的 true 都适用：签入的项目 .claude/settings.json 可以选择退出存储库中的这些连接器，但项目级别的 false 无法覆盖用户级别或托管级别的 true。", scope: "Any file", type: "布尔值", defaultText: "false，因此 Claude Code 获取您的连接器", example: "{\n  \"disableClaudeAiConnectors\": true\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "disableCommandPluginSources", category: "插件和技能", desc: "阻止 command 插件来源，它通过在用户机器上运行市场声明的命令来安装插件。当您将其设置为 true 时，Claude Code 永远不会运行该命令，不会安装或更新命令来源的插件，并停止加载已安装的插件。设置为 false 以明确允许它们。每当它阻止命令来源时，无论您将其设置为 true 还是在 allowManagedHooksOnly 下保持未设置，它也会阻止市场 headersHelper 命令，除了托管设置本身声明的市场。需要 Claude Code v2.1.229 或更高版本，headersHelper 阻止需要 v2.1.238 或更高版本。", scope: "Managed", type: "Boolean", defaultText: "未设置，因此 Claude Code 遵循 allowManagedHooksOnly：限制 hook 执行到托管设置的组织也会禁用命令来源", example: "{\n  \"disableCommandPluginSources\": true\n}", exampleFile: "managed-settings.json"),
        ClaudeSettingEntry(key: "disableDeepLinkRegistration", category: "远程、桌面和通知", desc: "阻止 Claude Code 向操作系统注册 claude-cli:// 协议处理程序，否则在你发送交互式会话的第一个提示后会进行注册。深链接允许外部工具使用预填充的提示打开 Claude Code 会话。在协议处理程序注册受限或单独管理的环境中设置此项。", scope: "任何文件", type: "字符串 \"disable\"", defaultText: "未设置，因此 Claude Code 注册处理程序", example: "{\n  \"disableDeepLinkRegistration\": \"disable\"\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "disableDesktopLocalSessions", category: "远程、桌面和通知", desc: "在桌面应用中关闭在设备上运行的 Code 会话，用于开发人员应该通过 SSH 在远程机器上工作的部署。在 Code 选项卡中，**本地**环境保留在环境下拉列表中，但呈灰显状态且无法选择，工具提示显示你的组织已关闭它；在 Windows 上，WSL 条目以相同方式呈灰显，尽管 WSL 会话是否在托管设备上运行由单独管理。新会话默认为第一个SSH 连接（如果已配置），应用拒绝在设备上启动或恢复会话，包括返回同一机器的 SSH 连接。到其他主机的 SSH 会话和云会话不受影响。桌面应用读取此键；终端 CLI 忽略它。需要 Claude Desktop v1.37937.0 或更高版本。", scope: "托管", type: "布尔值；仅 JSON 布尔值 true 生效", defaultText: "未设置，因此本地会话可用", example: "{\n  \"disableDesktopLocalSessions\": true\n}", exampleFile: "managed-settings.json"),
        ClaudeSettingEntry(key: "disableMobileSimulatorTools", category: "Tools", desc: "阻止 Claude 的工具用于桌面应用的 iOS 模拟器窗格。人员保持对窗格的手动使用；仅移除 Claude 的访问权限，任何人都无法从应用内部将其重新打开。桌面应用读取此密钥；终端 CLI 会忽略它。", scope: "Managed", type: "Boolean；仅 JSON Boolean true 生效", defaultText: "未设置，因此 Claude 的模拟器工具遵循桌面应用中每个人的设置切换", example: "{\n  \"disableMobileSimulatorTools\": true\n}", exampleFile: "managed-settings.json"),
        ClaudeSettingEntry(key: "disableRemoteControl", category: "远程、桌面和通知", desc: "关闭远程控制：Claude Code 随后拒绝 claude remote-control、--remote-control 标志、自动启动和会话内切换，并报告你的组织的策略已禁用它。将其放在托管设置中以进行每个设备的 MDM 强制执行。", scope: "任何文件", type: "布尔值", defaultText: "false", example: "{\n  \"disableRemoteControl\": true\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "disableSideloadFlags", category: "企业和托管设置", desc: "在启动时拒绝 --plugin-dir、--plugin-url、--agents 和 --mcp-config CLI 标志，用户可能会通过这些标志来绕过 strictKnownMarketplaces 进行单次运行。Claude Code 会以错误退出并命名被拒绝的标志，并对在内部使用这些标志启动 CLI 的表面应用相同的检查，目前在桌面应用中的 Cowork 本地会话。在云会话中，Claude Code 会删除服务器通过 --mcp-config 传递的 MCP 服务器，除了进程内 type: \"sdk\" 条目，并启动会话。需要 Claude Code v2.1.193 或更高版本。", scope: "Managed", type: "Boolean", defaultText: "false", example: "{\n  \"disableSideloadFlags\": true\n}", exampleFile: "managed-settings.json"),
        ClaudeSettingEntry(key: "disableSkillShellExecution", category: "插件和技能", desc: "关闭 skills 和来自用户、项目、插件或附加目录来源的自定义命令中 !... 和 ! 块的内联 shell 执行。Claude Code 用 [shell command execution disabled by policy] 替换每个命令，而不是运行它。", scope: "Any file。托管设置中的 true 无法被其他地方的 false 覆盖。", type: "Boolean", defaultText: "未设置，因此内联 shell 运行", example: "{\n  \"disableSkillShellExecution\": true\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "disableWorkflows", category: "Hooks 和自动化", desc: "关闭 动态工作流 和您的设置所涉及的每个人的捆绑工作流命令，例如通过托管设置的组织。要仅为自己打开或关闭工作流，请改用 enableWorkflows，这是 /config 中的 **动态工作流** 切换写入您的用户设置的内容。", scope: "任何文件", type: "布尔值", defaultText: "false", example: "{\n  \"disableWorkflows\": true\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "disabledMcpjsonServers", category: "MCP", desc: "拒绝项目 .mcp.json 文件中定义的特定服务器，以便 Claude Code 永远不会连接它们或要求您批准它们。任何设置文件中的拒绝都适用，包括签入存储库的项目 .claude/settings.json。", scope: "Any file", type: "字符串数组，服务器名称如 .mcp.json 中所示", defaultText: "未设置", example: "{\n  \"disabledMcpjsonServers\": [\"filesystem\"]\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "editorMode", category: "界面和终端", desc: "为输入提示选择快捷键绑定模式。", scope: "Any file", type: "string，值为以下之一：", defaultText: "\"normal\"", example: "{\n  \"editorMode\": \"vim\"\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "effortLevel", category: "模型和响应", desc: "为您尚未保存级别的模型设置默认努力级别。较低的级别在直接任务上更快且更便宜，较高的级别在复杂问题上推理更深入。 当您在您的机器上的交互式会话中运行 /effort low、medium、high 或 xhigh 时，Claude Code 将该级别保存到modelSettings下的活动模型，而不是写入此键。在 v2.1.251 之前，/effort 写入此键。 在同一设置文件中，Claude Code 使用模型的保存级别而不是此键。modelSettings说明跨文件优先级。 在附加到远程工作者的会话中、在 -p 运行中以及在 Agent SDK 中，/effort 仅适用于该会话。调整努力级别列出也仅适用于该会话的交互式选择。/effort 打印的消息说明发生了什么。", scope: "Any file", type: "string，其中之一：", defaultText: "未设置", example: "{\n  \"effortLevel\": \"xhigh\"\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "emojiCompletionEnabled", category: "界面和终端", desc: "当您在提示输入中键入 : 加上速记代码时显示表情符号建议，并将完成的速记代码（如 :heart:）替换为其表情符号。将其设置为 false 以关闭两者。", scope: "Any file", type: "Boolean", defaultText: "true", example: "{\n  \"emojiCompletionEnabled\": false\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "enableAllProjectMcpServers", category: "MCP", desc: "批准项目 .mcp.json 文件中定义的每个 MCP 服务器，无需提示。当您在批准对话框中选择批准所有服务器时，Claude Code 会将此密钥写入 .claude/settings.local.json。", scope: "Any file。在您尚未接受信任对话框的文件夹中，Claude Code 从用户设置、托管设置和 --settings 中遵守它，并在共享项目文件中忽略它，包括在会话中以及 claude mcp list 和 claude mcp get；项目服务器批准和工作区信任说明何时未跟踪的 .claude/settings.local.json 也计数。", type: "布尔值", defaultText: "未设置，因此 Claude Code 要求您批准每个服务器", example: "{\n  \"enableAllProjectMcpServers\": true\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "enableArtifact", category: "远程、桌面和通知", desc: "关闭 Artifact 工具，该工具将会话输出发布为 claude.ai 上的私有网页。当你在 /config 中关闭**Artifacts** 行时，Claude Code 会将此键写入你的用户设置，因此你通常不需要手动编辑它。需要 Claude Code v2.1.196 或更高版本。", scope: "任何文件。每个文件都可以关闭工具，但没有文件可以将其打开。", type: "布尔值", defaultText: "未设置，因此工具遵循你账户的可用性", example: "{\n  \"enableArtifact\": false\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "enableWorkflows", category: "Hooks 和自动化", desc: "当您的计划默认值不是您想要的时，为自己打开或关闭 动态工作流。在 /config 中显示为 **动态工作流**，它将此键写入您的用户设置，并在您切换回计划默认值时再次删除它。要从托管设置为每个人关闭工作流，请改用 disableWorkflows。", scope: "任何文件", type: "布尔值", defaultText: "未设置，因此工作流打开，除非您在 Pro 计划上，其中工作流关闭", example: "{\n  \"enableWorkflows\": true\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "enabledMcpjsonServers", category: "MCP", desc: "批准项目 .mcp.json 文件中定义的特定服务器，以便 Claude Code 连接它们而无需询问。当您在批准对话框中批准服务器时，Claude Code 会将此密钥写入 .claude/settings.local.json。", scope: "Any file。在您尚未接受信任对话框的文件夹中，Claude Code 从用户设置、托管设置和 --settings 中遵守它，并在共享项目文件中忽略它，包括在会话中以及 claude mcp list 和 claude mcp get；项目服务器批准和工作区信任说明何时未跟踪的 .claude/settings.local.json 也计数。", type: "字符串数组，服务器名称如 .mcp.json 中所示", defaultText: "未设置", example: "{\n  \"enabledMcpjsonServers\": [\"memory\", \"github\"]\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "enabledPlugins", category: "插件和技能", desc: "打开或关闭单个 plugins，由 plugin-name@marketplace-name 键控。在任何范围内没有条目的插件回退到其 defaultEnabled 值。当您使用 /plugin 或 claude plugin enable 启用或禁用插件时，Claude Code 为您写入此键。", scope: "Any file", type: "对象，将 plugin-name@marketplace-name 映射到 Boolean", defaultText: "未设置，因此每个插件遵循其 defaultEnabled 值", example: "{\n  \"enabledPlugins\": {\n    \"code-formatter@team-tools\": true,\n    \"deployment-tools@team-tools\": true,\n    \"experimental-features@personal\": false\n  }\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "enforceAvailableModels", category: "模型和响应", desc: "/model 选择器有一个**默认**选项，当应用时解析为您的组织默认模型，否则解析为您的账户类型的默认值。availableModels允许列表限制您可以命名的模型，但单独来说它不会改变**默认**，因此**默认**仍然可以解析为列表外的模型。此键关闭了该间隙。需要 Claude Code v2.1.175 或更高版本。 当您的组织部署任何托管设置时，Claude Code 仅从托管源读取此键，并在您的其他文件中忽略它。", scope: "Any file", type: "Boolean", defaultText: "false", example: "{\n  \"availableModels\": [\"sonnet\", \"haiku\"],\n  \"enforceAvailableModels\": true\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "env", category: "内存和上下文", desc: "为每个会话和 Claude Code 从中启动的子进程设置环境变量。环境变量参考中的任何变量都可以放在这里，这是如何将其应用于每个会话或向您的团队推出的方式。", scope: "Any file", type: "将变量名映射到字符串值的对象", defaultText: "未设置", example: "{\n  \"env\": {\n    \"DISABLE_AUTO_COMPACT\": \"1\",\n    \"ANTHROPIC_BASE_URL\": \"https://proxy.example.com\"\n  }\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "externalEditorContext", category: "全局配置设置", desc: "当你按 Ctrl+G 时，Claude Code 在你的外部编辑器中打开你正在输入的提示。启用此键后，编辑器缓冲区以 Claude 的上一个响应作为 # 注释行开始，因此你可以在写入时读取它，Claude Code 在你保存时删除这些行。在 /config 中显示为**在外部编辑器中显示最后响应**。", scope: "全局配置", type: "布尔值", defaultText: "false", example: "{\n  \"externalEditorContext\": true\n}", exampleFile: "~/.claude.json"),
        ClaudeSettingEntry(key: "extraKnownMarketplaces", category: "插件和技能", desc: "按名称注册其他插件市场，以便打开存储库的人或托管设置到达的每个人都获得市场，而无需自己添加。Claude Code 注册它还不知道的每个市场。enabledPlugins 从中命名的插件是否安装取决于插件的来源和哪个文件启用它；该条目有规则。", scope: "Any file。Claude Code 仅在您接受该文件夹的工作区信任对话后才接受存储库的 .claude/settings.json 或 .claude/settings.local.json 中的条目；在您未信任的文件夹中，包括 -p 运行，它会忽略它们而不显示消息。", type: "对象，将市场名称映射到具有 source 对象和可选 autoUpdate Boolean 的对象", defaultText: "未设置", example: "{\n  \"extraKnownMarketplaces\": {\n    \"acme-tools\": {\n      \"source\": {\n        \"source\": \"github\",\n        \"repo\": \"acme-corp/claude-plugins\"\n      }\n    },\n    \"security-plugins\": {\n      \"source\": {\n        \"source\": \"git\",\n        \"url\": \"https://git.example.com/security/plugins.git\"\n      }\n    }\n  }\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "fallbackModel", category: "模型和响应", desc: "命名备份模型供 Claude Code 在您的主模型过载或不可用时按顺序尝试。Claude Code 在链中的下一个可用模型上切换以完成该轮，并显示通知。没有链的情况下，Claude Code 重试同一模型，然后显示服务器的错误，您重试或自己切换模型。 切换意味着在备用模型上进行一轮冷提示缓存；您的下一条消息首先再次尝试主模型。", scope: "Any file", type: "模型别名或 ID 的数组；\"default\" 扩展为默认模型", defaultText: "未设置，因此失败的请求不会在另一个模型上重试", example: "{\n  \"fallbackModel\": [\"claude-sonnet-5\", \"claude-haiku-4-5\"]\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "fastMode", category: "模型和响应", desc: "为可用的会话打开快速模式，用于交互式工作，如快速迭代或实时调试，您希望以更高的每令牌成本获得速度。您通常不会手动编辑此键：运行 /fast 将 fastMode: true 写入 ~/.claude/settings.json，再次运行它以关闭快速模式会删除该键。快速模式仅在 Opus 5.5、Opus 5 和 Opus 4.8 上运行：从另一个模型打开它会将您切换到 Opus，切换到不支持的模型会关闭它。请参阅在快速模式打开时切换模型。", scope: "Any file", type: "Boolean", defaultText: "未设置，因此快速模式已关闭", example: "{\n  \"fastMode\": true\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "fastModePerSessionOptIn", category: "模型和响应", desc: "通常，运行 /fast 将fastMode保存到一个人的用户设置，因此快速模式在之后每个会话的开始时打开。将此键设置为 true 以停止这种情况：保存的 fastMode: true 不再在会话开始时打开快速模式，每个人必须在他们想要它的每个会话中运行 /fast。Claude Code 在他们的文件中保留 fastMode 键，因此关闭此键会恢复旧行为。 Team 或 Enterprise 计划的所有者可以通过服务器托管设置在组织范围内部署它。当托管设置设置该键时，/fast on 在交互式终端会话外被拒绝，并报告您的组织已禁用快速模式。这涵盖非交互式模式、VS Code 扩展和云会话。", scope: "Any file", type: "Boolean", defaultText: "false", example: "{\n  \"fastModePerSessionOptIn\": true\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "feedbackDrafts", category: "隐私和遥测", desc: "控制 Claude 起草的反馈：Claude 是否可以为您排队反馈草稿以供审查，以及 Claude Code 在 Claude 排队时是否显示卡片。", scope: "用户或托管", type: "字符串，\"notify\"、\"quiet\" 或 \"off\" 之一", defaultText: "\"notify\"", example: "{\n  \"feedbackDrafts\": \"quiet\"\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "feedbackSurveyRate", category: "隐私和遥测", desc: "设置会话质量调查在会话符合条件时出现的概率。设置 0 以防止调查出现。", scope: "任何文件", type: "0 到 1 之间的数字", defaultText: "未设置，因此 Claude Code 使用 Anthropic 远程设置的速率，或在 Amazon Bedrock、Google Cloud 的 Agent Platform 和 Microsoft Foundry 上的内置速率 0.005，这些不接收远程配置", example: "{\n  \"feedbackSurveyRate\": 0.05\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "fileCheckpointingEnabled", category: "内存和上下文", desc: "让 Claude Code 在每次编辑前快照文件，以便 /rewind 可以恢复它们。在 /config 中显示为**回退代码（检查点）**，在那里切换它会将此键写入您的用户设置。", scope: "Any file", type: "Boolean", defaultText: "true", example: "{\n  \"fileCheckpointingEnabled\": false\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "fileSuggestion", category: "界面和终端", desc: "运行您自己的命令来提供 @ 文件路径自动完成，而不是使用内置文件建议。内置建议使用快速文件系统遍历；大型单体仓库可能会通过项目特定的索引（如预构建的文件索引）做得更好。", scope: "Any file。在状态行和文件建议门下，Claude Code 关闭命令或仅运行托管值，并跳过您的而不发出警告。", type: "对象，包含 type（始终为 \"command\"）和 command（要运行的 shell 命令）", defaultText: "unset，所以 Claude Code 使用内置文件建议", example: "{\n  \"fileSuggestion\": {\n    \"type\": \"command\",\n    \"command\": \"~/.claude/file-suggestion.sh\"\n  }\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "footerLinksRegexes", category: "界面和终端", desc: "当正则表达式匹配转向输出时在输入框下方的页脚中渲染额外的可点击徽章：工具结果，包括文件内容和获取的页面，以及 Claude 自己的响应。使用它将项目 CLI 打印的 ID（如审查工具和问题跟踪器）转换为会话链接。", scope: "User or managed", type: "对象数组，每个对象的 type 设置为 \"regex\"、pattern 正则表达式、url 模板和可选的 label；url 和 label 中的 {name} 占位符从 pattern 中的命名捕获组填充", defaultText: "unset，所以不渲染徽章", example: "{\n  \"footerLinksRegexes\": [\n    {\n      \"type\": \"regex\",\n      \"pattern\": \"\\\\b(?<key>PROJ-\\\\d+)\\\\b\",\n      \"url\": \"https://issues.example.com/browse/{key}\",\n      \"label\": \"{key}\"\n    }\n  ]\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "forceLoginGatewayUrl", category: "身份验证和提供商", desc: "设置 /login Cloud gateway 屏幕连接到的网关 URL，以便人们可以到达您的 cloud gateway 而无需输入其地址。该屏幕没有 URL 字段：设置此密钥后，它显示您的网关 URL 并在人们按 Enter 时连接；不设置时，它告诉他们联系其 IT 管理员。 此密钥或 forceLoginMethod: \"gateway\" 使机器仅限网关，因此 /login 在 Cloud gateway 屏幕上打开，没有登录方法选择器。请参阅管理员策略需要 Cloud gateway 登录，了解剩余第一方登录或 API 密钥会发生什么。设置两个密钥，以便屏幕连接而不是显示错误。", scope: "Managed。仅从机器上的源读取：managed-settings.json、macOS plist 或 Windows HKLM 注册表或策略辅助程序。Claude Code 在 HKCU 和服务器托管设置中忽略它。", type: "string，包括方案的完整 URL", defaultText: "未设置，因此 Cloud gateway 屏幕显示错误，告诉人们联系其 IT 管理员", example: "{\n  \"forceLoginGatewayUrl\": \"https://claude-gateway.example.com\"\n}", exampleFile: "managed-settings.json"),
        ClaudeSettingEntry(key: "forceLoginMethod", category: "身份验证和提供商", desc: "限制人们可以使用哪种帐户登录。设置 \"claudeai\" 以仅允许 claude.ai 帐户，设置 \"console\" 以仅允许 Claude Console 帐户，或设置 \"gateway\" 以将人们发送到 cloud gateway 而不是第一方登录。管理员在托管设置中设置它，并将其与 forceLoginOrgUUID 配对，以将开发人员的 claude.ai 登录保持在一个组织内。如果您在任何设置文件中将其设置为 \"claudeai\" 或 \"console\"，Claude Code 也会停止在该文件适用的会话中提供无密钥 Console 登录。", scope: "Any file。Claude Code 仅从机器上的托管源（managed-settings.json、macOS plist 或 Windows HKLM 注册表或策略辅助程序）接受 \"gateway\"。它在用户、项目、本地、HKCU 和服务器托管设置中将 \"gateway\" 视为未设置，与 forceLoginGatewayUrl 的规则相同。", type: "string，以下之一：", defaultText: "未设置，因此人们选择登录方法", example: "{\n  \"forceLoginMethod\": \"claudeai\"\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "forceLoginOrgUUID", category: "身份验证和提供商", desc: "从托管源，要求 claude.ai 帐户登录属于一个 Anthropic 组织（给定为单个 UUID）或属于多个组织（给定为数组）。从任何设置文件，Claude Code 也使用单个 UUID 在 claude.ai 或 Claude Console 登录期间预选择该组织，对于数组预选择任何内容。如果您在任何设置文件中设置该密钥，Claude Code 也会停止在该文件适用的会话中提供无密钥 Console 登录，并改为创建 API 密钥。", scope: "Any file。仅托管源强制执行限制；任何其他设置文件中的单个 UUID 在登录期间预选择组织而不限制它。", type: "string，一个 UUID，或字符串数组，多个 UUID", defaultText: "未设置，因此任何组织都可以登录", example: "{\n  \"forceLoginOrgUUID\": [\"xxxxxxxx-xxxx-xxxx-xxxx-xxxxxxxxxxxx\", \"yyyyyyyy-yyyy-yyyy-yyyy-yyyyyyyyyyyy\"]\n}", exampleFile: "managed-settings.json"),
        ClaudeSettingEntry(key: "forceRemoteSettingsRefresh", category: "企业和托管设置", desc: "阻止 CLI 启动，直到 Claude Code 已经新鲜获取服务器管理的设置。如果获取失败，Claude Code 会退出而不是继续使用缓存或无设置。当您的环境无法接受即使是短暂的窗口（在该窗口中会话在没有其托管策略的情况下运行）时，请设置它。 当密钥未设置时，Claude Code 不会在获取时阻止启动，尽管当开发者在启动时登录时，它会等待最多五秒钟以进行获取。Cloud 网关会话总是等待，如果无法到达网关则退出。", scope: "Managed。Claude Code 从任何管理员控制的托管源（即使不是最高优先级源）中接受 true。", type: "Boolean", defaultText: "false", example: "{\n  \"forceRemoteSettingsRefresh\": true\n}", exampleFile: "managed-settings.json"),
        ClaudeSettingEntry(key: "gatewayInternalNetworks", category: "身份验证和提供商", desc: "声明您的组织从其内部网络编号的公共 IPv4 块，以便 /login 在那里接受 cloud gateway。需要 Claude Code v2.1.268 或更高版本。 没有此密钥，/login 连接到私有地址上的任何网关，仅此而已。有了它，/login 也接受列出的块内的网关，仅通过直接连接。该机器在该连接上的自身地址也必须在同一块内。", scope: "Managed。仅从机器上的源读取：managed-settings.json、macOS plist 或 Windows HKLM 注册表或策略辅助程序。Claude Code 在 HKCU 和服务器托管设置中忽略它。", type: "字符串数组，最多四个 IPv4 CIDR 块，每个 /8 到 /32，彼此不重叠，且都不与私有空间重叠。", defaultText: "未设置，因此 /login 仅接受私有地址上的网关", example: "{\n  \"gatewayInternalNetworks\": [\"203.0.113.0/24\"]\n}", exampleFile: "managed-settings.json"),
        ClaudeSettingEntry(key: "gcpAuthRefresh", category: "身份验证和提供商", desc: "运行您自己的命令以在 Claude Code 发现 Google Cloud Application Default Credentials 已过期或无法加载时刷新它们，以便 Google Cloud's Agent Platform 请求继续工作，而无需您手动重新身份验证。", scope: "Any file", type: "string，shell 命令行", defaultText: "未设置，因此 Claude Code 的凭证错误告诉您自己运行 gcloud auth application-default login", example: "{\n  \"gcpAuthRefresh\": \"gcloud auth application-default login\"\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "hooks", category: "Hooks 和自动化", desc: "在 Claude Code 的生命周期中的某些点（例如在工具调用之前或会话启动时）运行您自己的命令、提示、代理、HTTP 请求或 MCP 工具作为 hooks；hooks 参考 列出每个事件、其有效负载和其退出代码。每个事件映射到匹配器组列表，每个组列出在匹配器应用时运行的处理程序。", scope: "任何文件。Hooks 在文件中合并而不是相互替换，来自托管设置的 hooks 无法从其他文件中删除。", type: "由 hook 事件 键入的对象；每个值是 { \"matcher\", \"hooks\" } 组的数组，其 hooks 条目的 type 为 \"command\"、\"prompt\"、\"agent\"、\"http\" 或 \"mcp_tool\"", defaultText: "未设置，因此没有 hooks 运行", example: "{\n  \"hooks\": {\n    \"PreToolUse\": [\n      {\n        \"matcher\": \"Bash\",\n        \"hooks\": [\n          { \"type\": \"command\", \"command\": \"~/.claude/hooks/check-bash.sh\" }\n        ]\n      }\n    ]\n  }\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "httpHookAllowedEnvVars", category: "Hooks 和自动化", desc: "HTTP hook 可以将环境变量的值放入请求标头中，例如 Authorization: Bearer $HOOK_TOKEN 标头，但仅限于 hook 在其自己的 allowedEnvVars 中列出的变量。此键为每个 HTTP hook 的该列表设置外部限制：hook 只能使用变量（如果其自己的 allowedEnvVars 和此键都命名它）。使用它可以防止 hook 读取它不应该读取的秘密，即使 hook 的定义要求它。", scope: "任何文件。数组在设置文件中合并。", type: "环境变量名称数组", defaultText: "未设置，因此应用每个 hook 自己的 allowedEnvVars 列表", example: "{\n  \"httpHookAllowedEnvVars\": [\"MY_TOKEN\", \"HOOK_SECRET\"]\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "includeCoAuthoredBy", category: "Git 和归属", desc: "<Warning> 自 v2.0.62 起已弃用，当 attribution 替换它时。Claude Code 仍然读取它，但新配置应设置 attribution。 </Warning> 改用 attribution，它替换此键，让您可以分别更改或隐藏提交 trailer、拉取请求文本和会话链接。Claude Code 仍然遵守来自早于 attribution 的设置文件中的 includeCoAuthoredBy: false，但一旦设置 attribution.commit 或 attribution.pr，就会忽略它。", scope: "Any file", type: "布尔值", defaultText: "true", example: "{\n  \"includeCoAuthoredBy\": false\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "includeGitInstructions", category: "Git 和归属", desc: "Claude Code 向 Claude 提供两个与 git 相关的上下文片段：其内置的关于如何编写提交和拉取请求的说明（在 Bash 工具的描述中），以及您的存储库的 git 状态快照。快照包含当前分支、主分支、git status 输出和最近的提交。Claude Code 在会话开始时读取它。 将此键设置为 false 以将两者都排除，例如当您使用自己的 git 工作流技能时。", scope: "Any file", type: "布尔值", defaultText: "true", example: "{\n  \"includeGitInstructions\": false\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "inputNeededNotifEnabled", category: "远程、桌面和通知", desc: "当权限提示或问题等待你的输入时，在你的手机上获得推送通知。Claude Code 仅在远程控制连接时发送这些通知。在 /config 中显示为**需要操作时推送**。", scope: "任何文件。Claude Code 也会读取由旧版本留在 ~/.claude.json 中的值。", type: "布尔值", defaultText: "false", example: "{\n  \"inputNeededNotifEnabled\": true\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "isolatePeerMachines", category: "代理、会话和工作树", desc: "在 Claude 的 SendMessage 到达此机器之外的您的会话之前，需要您的明确批准；请参阅 Require approval for cross-machine messages。即使在 bypassPermissions mode 中，批准提示也会出现。", scope: "Any file。来自任何范围的 true 都适用，因此签入的项目文件可以打开要求但不能关闭。", type: "Boolean", defaultText: "未设置，因此跨机器消息不提示", example: "{\n  \"isolatePeerMachines\": true\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "keybindingFlavor", category: "界面和终端", desc: "<Warning> 自 v2.1.261 起已弃用，无效。提示的单词编辑键始终遵循 readline 约定，如在 Bash 中一样。Claude Code 仍然接受 keybindingFlavor，因此设置它的设置文件保持有效。 </Warning> 在 v2.1.238 到 v2.1.260 中，将其设置为 \"readline\" 使 Ctrl+W 删除回到前一个空格而不仅仅是前一个单词。", scope: "Any file", type: "string，\"classic\" 或 \"readline\"", defaultText: "unset", example: "", exampleFile: ""),
        ClaudeSettingEntry(key: "language", category: "模型和响应", desc: "默认情况下让 Claude 用英语以外的语言响应。响应没有固定列表：Claude Code 将值逐字传递给 Claude 作为始终用该语言响应的指令，因此任何 Claude 可以读取的语言名称都有效。Claude Code 不检查该值，因此拼写错误的名称按原样到达 Claude，而不是产生错误。相同的值为语音听写设置语言，它有一个固定的支持的听写语言列表，以及自动生成的会话标题。", scope: "Any file", type: "string，任何语言名称，例如 \"japanese\"、\"spanish\" 或 \"french\"；Claude Code 不验证它", defaultText: "未设置；会话标题然后匹配您的对话语言", example: "{\n  \"language\": \"japanese\"\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "managedMcpServers", category: "MCP", desc: "从托管设置向每个用户提供远程 MCP 服务器。用户保留他们自己添加的服务器，无法编辑或删除您提供的服务器。需要 Claude Code v2.1.259 或更高版本。", scope: "Managed。Claude Code 在用户、项目和本地设置中使用警告删除该密钥，并且不在 Claude Desktop 应用的代码选项卡中读取它（在第三方部署上）或在应用的 Cowork 会话中读取它，其中 Claude Desktop 提供并锁定这些会话的 MCP 服务器。", type: "按服务器名称键入的对象。每个条目都具有 http 或 sse 服务器的 .mcp.json 形状：必需的 https:// url，以及可选的 headers、oauth 和其他 HTTP 和 SSE 选项。Claude Code 删除验证失败的条目，条目可以包含的内容列出了条件", defaultText: "未设置，因此托管设置不提供任何服务器", example: "{\n  \"managedMcpServers\": {\n    \"search\": {\n      \"type\": \"http\",\n      \"url\": \"https://search.example.com/mcp\"\n    }\n  }\n}", exampleFile: "managed-settings.json"),
        ClaudeSettingEntry(key: "managedSourcesBehavior", category: "企业和托管设置", desc: "选择 Claude Code 是仅应用您的组织提供的最高优先级托管源，还是合并它提供的每个管理员源。默认情况下，Claude Code 采用携带策略密钥的最高优先级源并忽略其余的。策略密钥是除了这个密钥和 wslInheritsWindowsSettings 之外的任何设置密钥。因此，一旦服务器管理的设置或 MDM 策略提供策略密钥，managed-settings.json 文件仅贡献 Claude Code 从每个管理员源读取的密钥。使用 \"merge\"，您提供的每个管理员源都会将其密钥贡献给一个合并的策略。需要 Claude Code v2.1.242 或更高版本。 仅在您排名在最高优先级源下方的每个源都在管理员的控制下时设置 \"merge\"，因为 Claude Code 然后从较低源（例如 permissions.allow 规则）添加条目到策略。", scope: "Managed。Claude Code 从携带此密钥或策略密钥的最高优先级源读取此密钥，并忽略排名较低的每个源中的此密钥，因此较低源无法选择自己合并到上面的源。Windows HKCU 注册表和来自嵌入主机的父设置都不参与合并。", type: "string，其中之一：", defaultText: "\"first-wins\"", example: "{\n  \"managedSourcesBehavior\": \"merge\"\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "maxEffortLevel", category: "模型和响应", desc: "限制会话可以使用的努力级别，保留较低的级别可用。任何更高的级别都在上限处运行，包括来自 /effort、/model 选择器、--effort、CLAUDE_CODE_EFFORT_LEVEL、skill 或 subagent 的 effort frontmatter 或模型自己的默认值。Claude Code 在每个请求之前应用上限本身，因此它在每个提供商上都有效，包括 Amazon Bedrock、Google Cloud 的 Agent Platform 和 Microsoft Foundry。需要 Claude Code v2.1.267 或更高版本。", scope: "Any file。在托管设置中部署它以为组织强制执行。当多个范围设置上限时，最低的适用，因此在一个范围中设置的上限无法从另一个范围提高", type: "string，其中之一 \"low\"、\"medium\"、\"high\"、\"xhigh\" 或 \"max\"。\"max\" 值不设置上限", defaultText: "未设置，因此不适用上限", example: "{\n  \"maxEffortLevel\": \"medium\",\n  \"modelSettings\": {\n    \"claude-sonnet-4-6\": {\n      \"maxEffortLevel\": \"max\"\n    }\n  }\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "minimumVersion", category: "更新和版本控制", desc: "防止背景自动更新和 claude update 安装低于此版本的任何版本，因此移动到 \"stable\" 渠道不会从较新的 \"latest\" 构建中降级您。当您在 /config 中选择在切换渠道时保持当前版本时，Claude Code 会为您写入此键，当您切换回 \"latest\" 时会清除它。", scope: "Any file。在托管设置中设置以固定组织范围的最小值，用户和项目设置无法降低。", type: "string，版本号，例如 \"2.1.100\"；不是有效版本的值会被忽略", defaultText: "未设置，所以更新可以安装渠道提供的任何版本", example: "{\n  \"autoUpdatesChannel\": \"stable\",\n  \"minimumVersion\": \"2.1.100\"\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "model", category: "模型和响应", desc: "设置每个新会话使用的模型，因此您不必每次都使用 /model 选择一个。在此处设置它不会阻止您在会话中期切换。如果您的管理员设置了组织默认模型以覆盖用户选择，即使您在用户、项目或本地设置中设置此键，您也会获得该模型。", scope: "Any file", type: "string，模型别名或完整模型 ID", defaultText: "未设置，因此 Claude Code 使用您账户的默认模型", example: "{\n  \"model\": \"claude-sonnet-5\"\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "modelOverrides", category: "模型和响应", desc: "将 Anthropic 模型 ID 映射到提供商特定的模型 ID，例如 Amazon Bedrock 推理配置文件 ARN。然后每个模型选择器条目在调用提供商 API 时使用其映射值。管理员在Amazon Bedrock、Google Cloud 的 Agent Platform 和 Microsoft Foundry上使用这个来将每个模型版本路由到特定的推理配置文件、版本名称或部署，以实现治理、成本分配或区域路由。", scope: "Any file", type: "将模型 ID 映射到提供商模型 ID 的对象", defaultText: "未设置", example: "{\n  \"modelOverrides\": {\n    \"claude-opus-4-6\": \"arn:aws:bedrock:us-east-1:123456789012:inference-profile/example\"\n  }\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "modelPicker", category: "模型和响应", desc: "列出 /model 选择器提供的模型，按您写入它们的顺序和您选择的标签下，因此选择器列出您的组织运行的模型，在内置阵容之后或代替它。每行的 model 按字面意思取用，因此它接受 --model 接受的任何内容：别名如 opus、Anthropic 模型 ID 或 Amazon Bedrock、Google Cloud 的 Agent Platform、Microsoft Foundry 或 LLM 网关的提供商格式 ID。需要 Claude Code v2.1.242 或更高版本。", scope: "User or managed。Claude Code 从托管设置、--settings 和用户设置读取该键，并在项目和本地设置中忽略它，因此您克隆的存储库无法重新标记选择器。这三个中最高的设置该键的提供整个阵容，Claude Code 从不合并来自两个源的阵容。", type: "具有 options 数组和可选 replaceBuiltInOptions Boolean 的对象", defaultText: "未设置，因此选择器显示内置阵容", example: "{\n  \"modelPicker\": {\n    \"options\": [\n      { \"model\": \"us.anthropic.claude-opus-4-8\", \"label\": \"Opus (production)\" },\n      {\n        \"model\": \"us.anthropic.claude-sonnet-4-6\",\n        \"label\": \"Sonnet (production)\",\n        \"description\": \"Day-to-day work\"\n      }\n    ]\n  }\n}", exampleFile: "managed-settings.json"),
        ClaudeSettingEntry(key: "modelPricing", category: "模型和响应", desc: "以您的组织支付的费率而不是列表价格报告支出。当您的组织有合同费率时设置它，因此开发人员看到的美元数字与您的账单相匹配。Claude Code 在 /usage、状态行、Agent SDK 的 total_cost_usd、--max-budget-usd限制和OpenTelemetry成本指标和事件中应用费率。您提供费率：Claude Code 不从您的合同或 Claude Console 读取它们。需要 Claude Code v2.1.242 或更高版本。", scope: "Managed。通过服务器托管设置、MDM 策略、managed-settings.json 文件或策略助手部署该键。Claude Code 在用户、项目和本地设置中、在 --settings 中以及在 Windows 中的用户可写HKCU 注册表中忽略它。使用服务器托管设置，每个会话以列表价格报告成本，直到该会话的设置获取已确认该设置。嵌入 Claude Code 的主机应用程序，设置CLAUDE_CODE_PROVIDER_MANAGED_BY_HOST可以通过 SDK managedSettings选项提供自己的表，Claude Code 仅在没有托管源设置该键时使用，仅在 Claude Code v2.1.246 或更高版本中。", type: "具有可选 multiplier 和可选 overrides 映射的对象", defaultText: "未设置，因此 Claude Code 报告列表价格，除非主机应用程序提供表", example: "{\n  \"modelPricing\": {\n    \"multiplier\": 0.85,\n    \"overrides\": {\n      \"claude-sonnet-4-6\": {\n        \"input\": 2.4,\n        \"output\": 12,\n        \"cacheRead\": 0.24,\n        \"cacheWrite\": 3\n      }\n    }\n  }\n}", exampleFile: "managed-settings.json"),
        ClaudeSettingEntry(key: "modelSettings", category: "模型和响应", desc: "为您使用的每个模型保存努力级别。需要 Claude Code v2.1.251 或更高版本。 在您的机器上的交互式会话中，当您使用 /effort 或 /model 选择器的努力滑块将 low、medium、high 或 xhigh 保存为您的默认值时，Claude Code 在您使用的模型下在此处写入该级别，因此您很少自己编辑此键。当您在VS Code 扩展的模型选择器中选择这些级别之一时，Claude Code 以相同的方式在此处保存它。effortLevel条目列出 /effort 仅适用于该会话的会话。 手动编辑该键以更改或删除您保存的级别。 此处模型的 effortLevel 优先于同一设置文件中的顶级effortLevel。跨文件，Claude Code 分别解析每个模型：最高优先级设置文件，为该模型设置 effortLevel 或适用于该模型的顶级 effortLevel 决定，因此托管设置中的 effortLevel 优先于您在用户设置中保存的级别。调整努力级别列出还可以覆盖保存级别的内容，例如启动时的 --effort。 要限制一个模型的努力而不是设置其级别，请将maxEffortLevel字段添加到该模型的条目。该字段需要 Claude Code v2.1.267 或更高版本。", scope: "Any file", type: "将模型名称映射到具有 effortLevel 字段的对象的对象，其中之一 \"low\"、\"medium\"、\"high\" 或 \"xhigh\"、maxEffortLevel字段或两者", defaultText: "未设置", example: "{\n  \"modelSettings\": {\n    \"claude-opus-5-5\": {\n      \"effortLevel\": \"high\"\n    }\n  }\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "otelHeadersHelper", category: "身份验证和提供商", desc: "运行您自己的命令以生成 Claude Code 随 OpenTelemetry 导出发送的标头，用于令牌轮换的后端。Claude Code 在启动时运行它，之后定期运行，并期望在 stdout 上获得字符串标头值的 JSON 对象。", scope: "Any file", type: "string，可执行路径或 shell 命令行", defaultText: "未设置，因此 Claude Code 不添加辅助程序生成的标头", example: "{\n  \"otelHeadersHelper\": \"/bin/generate_otel_headers.sh\"\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "outputStyle", category: "模型和响应", desc: "按名称选择输出样式。输出样式是一组保存的指令，改变 Claude 的角色、语气和输出格式，例如内置的 Explanatory 和 Learning 样式或您自己写的。 如果您在会话期间更改此键，Claude 从您的下一条消息开始使用新样式。有关该消息在提示缓存中的成本，请参阅更改输出样式。在 v2.1.251 之前，编辑仅在您运行 /clear 或启动新会话后应用。", scope: "Any file", type: "string，内置或自定义输出样式的名称", defaultText: "未设置，因此 Claude Code 使用默认样式", example: "{\n  \"outputStyle\": \"Explanatory\"\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "parentSettingsBehavior", category: "企业和托管设置", desc: "选择 Claude Code 是否应用由嵌入主机进程（例如 Agent SDK 或 IDE 扩展）提供的托管设置，当管理员部署的托管层也存在时。使用 \"first-wins\"，Claude Code 会删除主机提供的设置；使用 \"merge\"，它通过限制性过滤器在管理员层下应用它们。当主机需要将其自己的限制传递给它启动的会话时，设置 \"merge\"，例如 Claude Desktop 传递网关的出口允许列表。", scope: "Managed。Claude Code 从最高优先级管理员控制的托管源读取它。", type: "string，其中之一：", defaultText: "\"first-wins\"", example: "{\n  \"parentSettingsBehavior\": \"merge\"\n}", exampleFile: "managed-settings.json"),
        ClaudeSettingEntry(key: "permissionExplainerEnabled", category: "全局配置设置", desc: "<Warning> 在 v2.1.257 中删除，以及 Bash 和 PowerShell 权限提示上的 Ctrl+E 命令说明。在当前版本中设置它没有效果。 </Warning> 在 v2.1.256 及更早版本中，你可以在 Bash 或 PowerShell 权限提示上按 Ctrl+E 查看模型生成的命令说明，并将此键设置为 false 以关闭该快捷键。", scope: "全局配置。在 v2.1.256 及更早版本上。", type: "布尔值", defaultText: "true", example: "", exampleFile: ""),
        ClaudeSettingEntry(key: "permissions", category: "权限设置", desc: "控制 Claude 可以在不询问的情况下使用哪些工具、哪些工具始终提示，以及哪些工具被阻止，并设置会话启动的权限模式。下面的每个 permissions.* 键都嵌套在此对象下。", scope: "Any file", type: "包含 allow、ask、deny、additionalDirectories、blockReadsOutsideWorkingDirectories、defaultMode、disableBypassPermissionsMode 和 disableAutoMode 的对象", defaultText: "未设置", example: "{\n  \"permissions\": {\n    \"allow\": [\"Bash(npm run *)\"],\n    \"ask\": [\"Bash(git push *)\"],\n    \"deny\": [\"Read(./.env)\"],\n    \"defaultMode\": \"acceptEdits\"\n  }\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "permissions.additionalDirectories", category: "权限设置", desc: "给予 Claude 对您启动的目录之外的目录的文件访问权限，作为额外的工作目录。大多数 .claude/ 配置未从这些目录发现。", scope: "Any file", type: "目录路径数组", defaultText: "未设置", example: "{\n  \"permissions\": {\n    \"additionalDirectories\": [\"../docs/\"]\n  }\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "permissions.allow", category: "权限设置", desc: "列出 Claude Code 在不询问您的情况下批准的工具使用。在 MCP 规则中，* 只能出现在 mcp__<server>__ 前缀之后的工具名称中，如 mcp__github__get_*；它不能出现在服务器名称中。", scope: "Any file", type: "权限规则字符串数组", defaultText: "未设置", example: "{\n  \"permissions\": {\n    \"allow\": [\"Bash(git diff *)\", \"Read(~/.zshrc)\"]\n  }\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "permissions.ask", category: "权限设置", desc: "列出即使在会否则批准它们的权限模式（如 acceptEdits 或 bypassPermissions）中也会提示您确认的工具使用。在 dontAsk 模式中，Claude Code 拒绝匹配的工具使用，而不是提示。", scope: "Any file", type: "权限规则字符串数组", defaultText: "未设置", example: "{\n  \"permissions\": {\n    \"ask\": [\"Bash(git push *)\"]\n  }\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "permissions.blockReadsOutsideWorkingDirectories", category: "权限设置", desc: "阻止 Claude 在每个权限模式（包括 bypassPermissions）中使用 Read、Grep、Glob 和 LSP 工具读取会话工作目录之外的路径。通过 Claude Code 识别的文件命令（如 cat）读取匹配路径的 Bash 命令会在自动模式和 bypassPermissions 模式中提示您。需要 Claude Code v2.1.257 或更高版本。 shell 解析器无法追踪的 Bash 命令（如多次更改目录或运行子 shell 的命令）会在自动模式和 bypassPermissions 模式中提示您。即使命令未命名工作目录之外的任何路径，提示也会出现。当命令在沙箱中运行且沙箱强制执行该块时，此提示不适用。 Claude Code 也会在此处写入 true，当您选择在自动模式的提示中阻止此类读取（在第一次读取工作目录之外之前）时。", scope: "Any file。如果任何设置源设置 true，则应用该块，因此存储库的签入文件可以为项目打开该块，但无法解除您设置的块。", type: "布尔值", defaultText: "未设置，因此工作目录之外的读取遵循您的权限模式和规则", example: "{\n  \"permissions\": {\n    \"blockReadsOutsideWorkingDirectories\": true\n  }\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "permissions.defaultMode", category: "权限设置", desc: "设置新会话启动的权限模式。当您将其留空时，会话会以您的计划和表面的内置默认值启动。", scope: "Any file。auto 和 bypassPermissions 不会从项目或本地设置生效，因此改为在 ~/.claude/settings.json 中设置它们。在 v2.1.257 之前，bypassPermissions 从任何文件生效。对于 VS Code 扩展启动的对话，Claude Code 仅读取用户、托管和 --settings 值。", type: "字符串，以下之一：", defaultText: "未设置", example: "{\n  \"permissions\": {\n    \"defaultMode\": \"acceptEdits\"\n  }\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "permissions.deny", category: "权限设置", desc: "列出 Claude Code 阻止的工具使用。将其用于保存 API 密钥、机密或环境值的文件：Claude Code 从文件发现和搜索结果中排除匹配的文件，拒绝读取它们，并在匹配的路径上阻止编辑和写入工具。读取和编辑拒绝规则适用于 Claude 的内置文件工具、Claude Code 在 Bash 中识别的文件命令（如 cat、head、tail、sed 和 tee）以及 Bash重定向的目标（如 > file 和 < file）；它们不适用于读取文件而不命名它们的命令（如 grep -r pattern .）或任意子进程，因此对于操作系统级别的强制执行，请启用沙箱。", scope: "Any file", type: "权限规则字符串数组", defaultText: "未设置", example: "{\n  \"permissions\": {\n    \"deny\": [\n      \"Read(./.env)\",\n      \"Read(./.env.*)\",\n      \"Read(./secrets/**)\",\n      \"Read(./config/credentials.json)\",\n      \"Bash(curl *)\"\n    ]\n  }\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "permissions.disableBypassPermissionsMode", category: "权限设置", desc: "防止任何人进入 bypassPermissions 模式。Claude Code 随后会拒绝 --dangerously-skip-permissions 标志，并忽略代理定义的 permissionMode: bypassPermissions，因此子代理使用父会话的权限模式运行。", scope: "Any file。通常在托管设置中设置以强制执行组织政策。", type: "字符串 \"disable\"", defaultText: "未设置", example: "{\n  \"permissions\": {\n    \"disableBypassPermissionsMode\": \"disable\"\n  }\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "plansDirectory", category: "内存和上下文", desc: "选择 Claude Code 在计划模式中写入的计划文件的存储位置。Claude Code 相对于项目根目录解析路径，当路径解析到项目外时保持默认值。", scope: "Any file", type: "字符串，相对于项目根目录的路径", defaultText: "未设置，因此 Claude Code 使用 ~/.claude/plans", example: "{\n  \"plansDirectory\": \"./plans\"\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "pluginConfigs", category: "插件和技能", desc: "存储您给插件的 userConfig 配置对话的非敏感答案，由插件 ID 键控。当您填写对话时，Claude Code 将此键写入您的用户设置，因此您无需手动编辑它。Claude Code 将敏感选项存储在 macOS Keychain 中，当 Keychain 拒绝写入时回退到 ~/.claude/.credentials.json；在没有支持的 keychain 的平台上，它将它们存储在 ~/.claude/.credentials.json。", scope: "User or managed", type: "对象，将插件 ID 映射到具有 options 字段的对象，将每个选项名称映射到字符串、数字、Boolean 或字符串数组，以及可选的 mcpServers 字段，以相同形状保存每个服务器的用户配置值", defaultText: "未设置", example: "{\n  \"pluginConfigs\": {\n    \"deployer@acme-tools\": {\n      \"options\": {\n        \"api_endpoint\": \"https://api.example.com\"\n      }\n    }\n  }\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "pluginSuggestionMarketplaces", category: "插件和技能", desc: "命名其插件可以显示为上下文安装建议的市场，在微调提示和固定在 /plugin **Discover** 选项卡顶部。内置的第一方前端设计提示不受影响。建议来自每个插件在其市场条目中的 relevance 声明。", scope: "Managed", type: "市场名称数组", defaultText: "未设置，因此没有市场声明的建议出现", example: "{\n  \"pluginSuggestionMarketplaces\": [\"acme-corp-plugins\"]\n}", exampleFile: "managed-settings.json"),
        ClaudeSettingEntry(key: "pluginTrustMessage", category: "插件和技能", desc: "将您组织自己的文本添加到 Claude Code 在安装前显示的插件信任警告中，例如确认来自您内部市场的插件已被审查。", scope: "Managed", type: "字符串", defaultText: "未设置，因此 Claude Code 仅显示标准警告", example: "{\n  \"pluginTrustMessage\": \"All plugins from our marketplace are approved by IT\"\n}", exampleFile: "managed-settings.json"),
        ClaudeSettingEntry(key: "policyHelper", category: "企业和托管设置", desc: "运行您部署的可执行文件，在启动时计算托管设置，因此您可以从设备状态、身份或远程服务而不是静态文件派生策略。Claude Code 在接受第一个提示之前运行帮助程序，并将其发出的设置视为会话的托管设置。", scope: "Managed。从 macOS plist、Windows HKLM 注册表或托管设置文件读取。Claude Code 从携带策略密钥的最高优先级托管源读取密钥，并仅当该源是这三个之一时才运行帮助程序；它忽略服务器管理的设置、HKCU 注册表和主机提供的父设置中的密钥。", type: "具有 path、timeoutMs 和 refreshIntervalMs 的对象", defaultText: "未设置，因此不运行帮助程序", example: "{\n  \"policyHelper\": {\n    \"path\": \"/usr/local/bin/claude-policy\",\n    \"timeoutMs\": 5000,\n    \"refreshIntervalMs\": 300000\n  }\n}", exampleFile: "managed-settings.json"),
        ClaudeSettingEntry(key: "policyHelper.path", category: "企业和托管设置", desc: "命名 Claude Code 运行的帮助程序可执行文件。有关路径违反以下规则时发生的情况，请参阅帮助程序失败。", scope: "Managed。从 macOS plist、Windows HKLM 注册表或托管设置文件读取，无论 policyHelper 在哪里读取。", type: "string，规范化形式的绝对路径，没有 . 或 .. 段；在 Windows 上，以 .exe 结尾的驱动器字母或 UNC 路径", defaultText: "无；当设置 policyHelper 时需要", example: "{\n  \"policyHelper\": {\n    \"path\": \"/usr/local/bin/claude-policy\"\n  }\n}", exampleFile: "managed-settings.json"),
        ClaudeSettingEntry(key: "policyHelper.refreshIntervalMs", category: "企业和托管设置", desc: "让 Claude Code 在后台按间隔重新运行帮助程序，以便策略更改到达运行中的会话。当刷新成功时，其输出替换之前的托管设置而不重启；当刷新失败时，Claude Code 保持它已有的策略。", scope: "Managed。从 macOS plist、Windows HKLM 注册表或托管设置文件读取，无论 policyHelper 在哪里读取。", type: "integer，毫秒：0 禁用刷新，否则至少 60000", defaultText: "未设置，因此 Claude Code 仅在启动时运行帮助程序一次", example: "{\n  \"policyHelper\": {\n    \"path\": \"/usr/local/bin/claude-policy\",\n    \"refreshIntervalMs\": 300000\n  }\n}", exampleFile: "managed-settings.json"),
        ClaudeSettingEntry(key: "policyHelper.timeoutMs", category: "企业和托管设置", desc: "设置 Claude Code 在将运行视为失败之前等待帮助程序的时间。超时的运行失败方式与非零退出相同，因此在启动时 Claude Code 拒绝启动。", scope: "Managed。从 macOS plist、Windows HKLM 注册表或托管设置文件读取，无论 policyHelper 在哪里读取。", type: "integer，毫秒，最小 1000", defaultText: "10000", example: "{\n  \"policyHelper\": {\n    \"path\": \"/usr/local/bin/claude-policy\",\n    \"timeoutMs\": 5000\n  }\n}", exampleFile: "managed-settings.json"),
        ClaudeSettingEntry(key: "prUrlTemplate", category: "Git 和归属", desc: "将 Claude Code 呈现的 PR 链接（在页脚徽章和工具结果摘要中）指向内部代码审查工具而不是 github.com。Claude Code 从 PR URL 替换 {host}、{owner}、{repo}、{number} 和 {url}。GitLab 合并请求 两个表面上的链接保持其 GitLab URL。", scope: "Any file", type: "字符串，使用五个占位符中任何一个的 URL 模板", defaultText: "未设置", example: "{\n  \"prUrlTemplate\": \"https://reviews.example.com/{owner}/{repo}/pull/{number}\"\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "preferredNotifChannel", category: "远程、桌面和通知", desc: "选择 Claude Code 在任务完成或权限提示等待时如何通知你。在 /config 中显示为**本地通知**。", scope: "任何文件。Claude Code 也会读取由旧版本留在 ~/.claude.json 中的值。", type: "字符串，以下之一：", defaultText: "\"auto\"", example: "{\n  \"preferredNotifChannel\": \"terminal_bell\"\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "prefersReducedMotion", category: "界面和终端", desc: "减少或关闭界面动画，如加载动画、闪烁和闪光效果。在 /config 中显示为**减少动画**。", scope: "Any file", type: "Boolean", defaultText: "false", example: "{\n  \"prefersReducedMotion\": true\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "processWrapper", category: "代理、会话和工作树", desc: "在 macOS 和 Linux 上，在 Claude Code 启动的后台进程 前面放置公司启动器命令。Claude Code 使用其自己的命令行附加运行启动器，因此启动器必须执行到 Claude Code；请参阅 Run Claude Code behind a corporate launcher 了解启动器合约。需要 Claude Code v2.1.210 或更高版本。", scope: "User or managed", type: "string，启动器命令作为 argv 前缀，例如带有可选参数的绝对路径", defaultText: "未设置，因此后台进程启动时不包装", example: "{\n  \"processWrapper\": \"/opt/corp/launcher --profile claude\"\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "promptCacheTtl", category: "模型和响应", desc: "选择提示缓存保持主对话的时间长度。此键适用于您的交互式、-p 和 Agent SDK 轮，以及 Claude Code 与它们内联运行的助手。一小时的生命周期在较长的中断中保持缓存温暖，API 以比五分钟生命周期更高的费率为每个缓存写入计费。需要 Claude Code v2.1.242 或更高版本。", scope: "Any file", type: "string，其中之一：", defaultText: "未设置，因此每个主对话请求获得其默认生命周期", example: "{\n  \"promptCacheTtl\": \"1h\",\n  \"subagentPromptCacheTtl\": \"5m\"\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "promptSuggestionEnabled", category: "界面和终端", desc: "显示或隐藏提示建议，即在您的提示输入中出现的灰显预测。将其设置为 false，或在 /config 中关闭**提示建议**，以隐藏它们。", scope: "Any file", type: "Boolean", defaultText: "true", example: "{\n  \"promptSuggestionEnabled\": false\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "remote.defaultEnvironmentId", category: "远程、桌面和通知", desc: "为你从 CLI 创建的云会话（例如使用 claude --cloud）选择默认云环境。当你使用 /remote-env 选择环境时，Claude Code 会将此键写入你的用户设置。", scope: "任何文件。对于自托管环境 ID，仅用户或托管设置或 --settings 标志。", type: "字符串，环境 ID，如 env_... 或 ccpool_...", defaultText: "未设置，因此当你的列表有 Anthropic 托管环境时 Claude Code 使用它，否则使用列表中不是远程控制桥接环境的第一个环境，或当每个都是桥接环境时使用第一个环境", example: "{\n  \"remote\": {\n    \"defaultEnvironmentId\": \"env_0123abcd\"\n  }\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "remoteControlAtStartup", category: "远程、桌面和通知", desc: "当每个交互式会话启动时自动连接远程控制，而不是等待 /remote-control。将其设置为 true 以打开自动连接，false 以关闭。在 /config 中显示为**为所有会话启用远程控制**。", scope: "任何文件。Claude Code 也会读取由旧版本留在 ~/.claude.json 中的值。", type: "布尔值", defaultText: "未设置，因此自动连接遵循你的组织的管理员默认值（如果已设置），否则遵循 Claude Code 的当前默认值", example: "{\n  \"remoteControlAtStartup\": true\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "requiredMaximumVersion", category: "更新和版本控制", desc: "设置您的组织允许启动的最新 Claude Code 版本。当运行版本较新时，Claude Code 在启动时退出，并告诉用户通过您组织的批准方法安装批准的版本；claude install <version> 也可能有效。需要 Claude Code v2.1.163 或更高版本。", scope: "Managed。Claude Code 在其他地方忽略该键时不会发出警告。", type: "string，版本号，例如 \"2.1.150\"；不是有效版本的值会被忽略", defaultText: "未设置，所以不适用上限", example: "{\n  \"requiredMaximumVersion\": \"2.1.150\"\n}", exampleFile: "managed-settings.json"),
        ClaudeSettingEntry(key: "requiredMinimumVersion", category: "更新和版本控制", desc: "设置您的组织允许启动的最旧 Claude Code 版本。当运行版本较旧时，Claude Code 在启动时退出，并告诉用户通过您组织的批准方法进行更新。检查仅在启动时运行，因此已在运行的会话会继续。需要 Claude Code v2.1.163 或更高版本。", scope: "Managed。Claude Code 在其他地方忽略该键时不会发出警告。", type: "string，版本号，例如 \"2.1.150\"；不是有效版本的值会被忽略", defaultText: "未设置，所以不适用下限", example: "{\n  \"requiredMinimumVersion\": \"2.1.150\"\n}", exampleFile: "managed-settings.json"),
        ClaudeSettingEntry(key: "respectGitignore", category: "界面和终端", desc: "控制 @ 文件选择器是否排除与 .gitignore 模式匹配的文件。在 /config 中显示为**在文件选择器中尊重 .gitignore**。", scope: "Any file。当没有设置文件设置它时，Claude Code 回退到 ~/.claude.json 中的 respectGitignore，这是 /config 切换写入的。", type: "Boolean", defaultText: "true", example: "{\n  \"respectGitignore\": false\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "respondToBashCommands", category: "界面和终端", desc: "选择在您使用输入框中的 ! 前缀运行 shell 命令后 Claude 是否响应。默认情况下，Claude Code 将命令的输出添加到对话中，Claude 对其进行回复。将此键设置为 false 以将输出添加到上下文而不进行回复，以便您可以运行多个命令并一起询问它们。需要 Claude Code v2.1.186 或更高版本。", scope: "Any file", type: "Boolean", defaultText: "true", example: "{\n  \"respondToBashCommands\": false\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "sandbox", category: "Sandbox 设置", desc: "使用 sandboxing 将 Claude 运行的 Bash 命令与您的文件系统和网络隔离。使用 enabled 打开沙箱，然后使用 filesystem、network 和 credentials 子对象缩小或扩大沙箱命令可以接触的内容。沙箱在 macOS、Linux 和 WSL2 上运行。", scope: "Any file", type: "对象，包含 enabled、failIfUnavailable、autoAllowBashIfSandboxed、excludedCommands、allowUnsandboxedCommands、enableWeakerNestedSandbox、enableWeakerNetworkIsolation、allowAppleEvents、bwrapPath、socatPath、ignoreViolations 和 ripgrep，以及 filesystem、network 和 credentials 对象", defaultText: "未设置，因此 Claude Code 运行命令时不使用沙箱", example: "{\n  \"sandbox\": {\n    \"enabled\": true,\n    \"autoAllowBashIfSandboxed\": true,\n    \"excludedCommands\": [\"docker *\"],\n    \"filesystem\": {\n      \"allowWrite\": [\"/tmp/build\", \"~/.kube\"],\n      \"denyRead\": [\"~/.aws/credentials\"]\n    },\n    \"network\": {\n      \"allowedDomains\": [\"github.com\", \"*.npmjs.org\"]\n    }\n  }\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "sandbox.allowAppleEvents", category: "Sandbox 设置", desc: "让 macOS 上的沙箱化命令发送 Apple Events，open、osascript 和在浏览器中打开 URL 的工具需要它；没有它们会失败，错误为 -600。这删除了代码执行隔离：沙箱化命令可以在没有用户提示的情况下启动其他应用程序，并可以向运行的应用程序（如 Terminal）发送 AppleScript 命令，受每个应用程序的 macOS 自动化同意提示 (TCC) 约束。", scope: "User or managed", type: "布尔值", defaultText: "false", example: "{\n  \"sandbox\": {\n    \"enabled\": true,\n    \"allowAppleEvents\": true\n  }\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "sandbox.allowUnsandboxedCommands", category: "Sandbox 设置", desc: "让 Claude 在沙箱阻止后使用 dangerouslyDisableSandbox 参数在沙箱外重试命令。将其设置为 false 以使 Claude Code 完全忽略该参数，并且 Claude 运行的每个命令都必须进行沙箱处理或出现在 excludedCommands 中。/sandbox **Overrides** 选项卡将该状态显示为 **Strict sandbox mode**。在托管设置中使用 false 以获得需要严格沙箱处理的策略。", scope: "Any file", type: "布尔值", defaultText: "true", example: "{\n  \"sandbox\": {\n    \"enabled\": true,\n    \"allowUnsandboxedCommands\": false\n  }\n}", exampleFile: "managed-settings.json"),
        ClaudeSettingEntry(key: "sandbox.autoAllowBashIfSandboxed", category: "Sandbox 设置", desc: "让 Claude Code 运行沙箱化的 Bash 命令而无需权限提示。无法在沙箱中运行的命令仍会通过常规权限流程，deny 规则和内容范围的 ask 规则（如 Bash(git push *) ）仍然适用；对于沙箱化命令，裸 Bash ask 规则被跳过。将其设置为 false 以也通过常规权限流程发送沙箱化命令，/sandbox **Mode** 选项卡称之为常规权限模式。", scope: "Any file", type: "布尔值", defaultText: "true", example: "{\n  \"sandbox\": {\n    \"enabled\": true,\n    \"autoAllowBashIfSandboxed\": false\n  }\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "sandbox.bwrapPath", category: "Sandbox 设置", desc: "将沙箱指向安装在 PATH 外的 bubblewrap 二进制文件，例如在气隙主机上的供应商副本。Claude Code 在启动依赖项检查和包装每个沙箱化命令时都使用该路径。", scope: "Managed。Claude Code 仅从托管设置读取它，以便用户、项目或本地文件无法将沙箱指向不同的二进制文件。", type: "字符串，绝对路径；Claude Code 删除相对路径并回退到 PATH 查找", defaultText: "未设置，因此 Claude Code 在 PATH 上找到 bwrap", example: "{\n  \"sandbox\": {\n    \"enabled\": true,\n    \"bwrapPath\": \"/opt/admin/bwrap\"\n  }\n}", exampleFile: "managed-settings.json"),
        ClaudeSettingEntry(key: "sandbox.credentials", category: "Sandbox 设置", desc: "声明凭证文件和环境变量以 protect from sandboxed commands。每个条目命名文件 path 或变量 name 和 mode：deny 在沙箱内隐藏凭证，mask 向沙箱化命令显示占位符，同时 sandbox proxy 在出站请求上替换真实值。Claude Code 仅保护您列出的条目；没有内置凭证拒绝列表。需要 Claude Code v2.1.187 或更高版本。", scope: "Any file。Claude Code 仅从用户设置、托管设置和 --settings 标志遵守 mask 条目、allowPlaintextInject、awsPairs 和 sigv4。", type: "对象，包含 files、envVars、allowPlaintextInject、awsPairs 和 sigv4", defaultText: "未设置，因此没有凭证被保护", example: "{\n  \"sandbox\": {\n    \"credentials\": {\n      \"files\": [{ \"path\": \"~/.aws/credentials\", \"mode\": \"deny\" }],\n      \"envVars\": [{ \"name\": \"GITHUB_TOKEN\", \"mode\": \"deny\" }]\n    }\n  }\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "sandbox.credentials.allowPlaintextInject", category: "Sandbox 设置", desc: "允许 mask 替换在纯 HTTP 请求以及 TLS 终止的 HTTPS 上。在纯 HTTP 上，上游身份未验证，凭证以明文形式传输，因此在受信任的测试网络外保持关闭。需要 Claude Code v2.1.199 或更高版本。", scope: "User or managed", type: "布尔值", defaultText: "false", example: "{\n  \"sandbox\": {\n    \"credentials\": {\n      \"allowPlaintextInject\": true\n    }\n  }\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "sandbox.credentials.awsPairs", category: "Sandbox 设置", desc: "分组掩盖的环境变量，形成一个 AWS 凭证用于 SigV4 re-signing，当您的凭证存在于具有非标准名称的变量中时。Claude Code 在您掩盖其整个值时自动链接常规 AWS_ACCESS_KEY_ID、AWS_SECRET_ACCESS_KEY 和 AWS_SESSION_TOKEN 三元组，因此您仅在其他名称时需要此键。需要 Claude Code v2.1.224 或更高版本。", scope: "User or managed", type: "对象数组，每个包含 accessKeyIdVar、secretAccessKeyVar 和可选的 sessionTokenVar，命名 sandbox.credentials.envVars 条目", defaultText: "未设置，因此仅配对常规三元组", example: "{\n  \"sandbox\": {\n    \"credentials\": {\n      \"awsPairs\": [\n        {\n          \"accessKeyIdVar\": \"MY_KEY_ID\",\n          \"secretAccessKeyVar\": \"MY_SECRET_KEY\",\n          \"sessionTokenVar\": \"MY_SESSION_TOKEN\"\n        }\n      ]\n    }\n  }\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "sandbox.credentials.envVars", category: "Sandbox 设置", desc: "保护环境变量免受沙箱化命令。使用 \"mode\": \"deny\"，Claude Code 从沙箱化命令的环境中删除变量。使用 \"mode\": \"mask\"，沙箱化命令看到每个会话的哨兵值，沙箱代理在对该条目的 injectHosts 的出站请求上替换真实值，因此 gh 和 npm 等工具保持认证而无需持有真实凭证。需要 Claude Code v2.1.187 或更高版本，\"mode\": \"mask\" 需要 v2.1.199 或更高版本。", scope: "Any file。Claude Code 从项目 .claude/settings.json 和本地 .claude/settings.local.json 删除 mask 条目。", type: "对象数组，每个包含 name 和 \"deny\" 或 \"mask\" 的 mode，加上可选的 mask fields for environment variables", defaultText: "未设置，因此没有环境变量被保护", example: "{\n  \"sandbox\": {\n    \"credentials\": {\n      \"envVars\": [\n        { \"name\": \"NPM_TOKEN\", \"mode\": \"deny\" },\n        { \"name\": \"GITHUB_TOKEN\", \"mode\": \"mask\", \"injectHosts\": [\"api.github.com\"] }\n      ]\n    }\n  }\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "sandbox.credentials.files", category: "Sandbox 设置", desc: "保护凭证文件或目录免受沙箱化命令。使用 \"mode\": \"deny\"，Claude Code 阻止在沙箱内读取路径，与 sandbox.filesystem.denyRead 相同的读取块。使用 \"mode\": \"mask\"，Linux 和 WSL2 上的沙箱化命令读取文件的哨兵副本，沙箱代理在对该条目的 injectHosts 的出站请求上替换真实值；在 macOS 上，文件在沙箱内不可读。需要 Claude Code v2.1.187 或更高版本，\"mode\": \"mask\" 需要 v2.1.221 或更高版本。", scope: "Any file。Claude Code 从项目 .claude/settings.json 和本地 .claude/settings.local.json 删除 mask 条目。", type: "对象数组，每个包含 path 和 \"deny\" 或 \"mask\" 的 mode，加上可选的 mask fields for files", defaultText: "未设置，因此没有凭证文件被保护", example: "{\n  \"sandbox\": {\n    \"credentials\": {\n      \"files\": [\n        { \"path\": \"~/.aws/credentials\", \"mode\": \"deny\" },\n        { \"path\": \"~/.config/gh/hosts.yml\", \"mode\": \"mask\", \"injectHosts\": [\"api.github.com\"] }\n      ]\n    }\n  }\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "sandbox.credentials.sigv4", category: "Sandbox 设置", desc: "选择沙箱代理对 AWS 请求形式的处理，它 can't re-sign：streaming 用于 aws-chunked 流上传，presigned 用于预签名 URL，sigv4a 用于 SigV4A 非对称签名。这仅适用于使用掩盖对的占位符访问密钥 ID 签名的请求。需要 Claude Code v2.1.224 或更高版本。", scope: "User or managed", type: "对象，包含 streaming、presigned 和 sigv4a，每个为以下之一：", defaultText: "未设置，因此每种形式都是 \"deny\"", example: "{\n  \"sandbox\": {\n    \"credentials\": {\n      \"sigv4\": {\n        \"streaming\": \"passthrough\"\n      }\n    }\n  }\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "sandbox.enableWeakerNestedSandbox", category: "Sandbox 设置", desc: "在无特权 Docker 容器内运行 Linux 沙箱，其中 bubblewrap 无法挂载新的 /proc。相反，内部沙箱绑定挂载容器的现有 /proc，这暴露了新挂载会隐藏的进程信息。这降低了安全性；仅当外部容器已提供您需要的隔离时才使用它。", scope: "Any file", type: "布尔值", defaultText: "false", example: "{\n  \"sandbox\": {\n    \"enabled\": true,\n    \"enableWeakerNestedSandbox\": true\n  }\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "sandbox.enableWeakerNetworkIsolation", category: "Sandbox 设置", desc: "让 macOS 上的沙箱化命令到达系统 TLS 信任服务 com.apple.trustd.agent。基于 Go 的工具（如 gh、gcloud 和 terraform ）在您使用 network.httpProxyPort 与 MITM 代理和自定义 CA 时需要它来验证 TLS 证书。这通过打开通过信任服务的潜在数据泄露路径来降低安全性。", scope: "Any file", type: "布尔值", defaultText: "false", example: "{\n  \"sandbox\": {\n    \"enabled\": true,\n    \"enableWeakerNetworkIsolation\": true\n  }\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "sandbox.enabled", category: "Sandbox 设置", desc: "为 Bash 命令打开 sandboxing。当您在 /sandbox 面板中选择一个模式时，Claude Code 会将此键写入当前项目的 .claude/settings.local.json；在 ~/.claude/settings.json 中设置它以对每个项目进行沙箱处理。", scope: "Any file", type: "布尔值", defaultText: "false", example: "{\n  \"sandbox\": {\n    \"enabled\": true\n  }\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "sandbox.excludedCommands", category: "Sandbox 设置", desc: "命名 Claude Code 在沙箱外运行的命令，例如在沙箱下不工作的工具。每个条目使用与 Bash(...) permission rule 内容相同的语法：精确命令、前缀（如 docker * ）或通配符模式。 您的条目仅当它们覆盖复合命令中的每个命令时才将 Bash 调用从沙箱中取出，某些调用形式即使这样也保持沙箱化。单独的 docker * 条目不会将 npm ci && docker build . 从沙箱中取出。", scope: "Any file", type: "命令模式数组", defaultText: "未设置，因此没有命令被排除", example: "{\n  \"sandbox\": {\n    \"excludedCommands\": [\"docker *\"]\n  }\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "sandbox.failIfUnavailable", category: "Sandbox 设置", desc: "当 sandbox.enabled 为 true 但沙箱无法启动时（因为缺少依赖项或不支持该平台），使 Claude Code 在启动时以错误退出。没有它，Claude Code 会显示警告并运行未沙箱化的命令。在托管设置中使用它，当您的组织要求沙箱作为硬门时。", scope: "Any file", type: "布尔值", defaultText: "false", example: "{\n  \"sandbox\": {\n    \"enabled\": true,\n    \"failIfUnavailable\": true\n  }\n}", exampleFile: "managed-settings.json"),
        ClaudeSettingEntry(key: "sandbox.filesystem", category: "Sandbox 设置", desc: "控制沙箱化命令可以读取和写入的路径。默认情况下，它们可以写入工作目录、会话临时目录以及使用 --add-dir、/add-dir 或 permissions.additionalDirectories 添加的目录，并可以读取文件系统的其余部分，包括凭证文件。使用四个路径列表扩大或缩小范围，或使用 disabled 关闭文件系统层。请参阅 Filesystem isolation 了解默认边界。", scope: "Any file", type: "对象，包含 allowWrite、denyWrite、denyRead 和 allowRead 数组，以及 allowManagedReadPathsOnly 和 disabled 布尔值", defaultText: "未设置，因此应用默认读写边界", example: "{\n  \"sandbox\": {\n    \"filesystem\": {\n      \"allowWrite\": [\"/tmp/build\", \"~/.kube\"],\n      \"denyRead\": [\"~/.aws/credentials\"]\n    }\n  }\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "sandbox.filesystem.allowManagedReadPathsOnly", category: "Sandbox 设置", desc: "仅遵守来自托管设置的 allowRead 条目，以便开发人员无法重新打开对您的组织阻止的路径的读取访问。Claude Code 仍然从会话加载的每个设置范围合并 denyRead 条目。", scope: "Managed", type: "布尔值", defaultText: "false", example: "{\n  \"sandbox\": {\n    \"filesystem\": {\n      \"denyRead\": [\"~/\"],\n      \"allowRead\": [\"~/work\"],\n      \"allowManagedReadPathsOnly\": true\n    }\n  }\n}", exampleFile: "managed-settings.json"),
        ClaudeSettingEntry(key: "sandbox.filesystem.allowRead", category: "Sandbox 设置", desc: "重新打开 denyRead 阻止的区域内特定路径的读取，以构建仅工作区读取访问。精确或通配符 denyRead 条目在更广泛的 allowRead 内保持阻止，如 overlap table 所示。当通配符 denyRead 条目（如 ~/**/.env ）匹配目录时，Claude Code 也会阻止其内容的读取。在 v2.1.236 之前的 macOS 上，Claude Code 在更广泛的 allowRead 条目覆盖它们的任何地方重新打开通配符 denyRead 条目匹配的路径，并保持匹配目录的内容可读。", scope: "Any file", type: "路径字符串数组，使用 sandbox path prefixes", defaultText: "未设置", example: "{\n  \"sandbox\": {\n    \"filesystem\": {\n      \"denyRead\": [\"~/\"],\n      \"allowRead\": [\".\"]\n    }\n  }\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "sandbox.filesystem.allowWrite", category: "Sandbox 设置", desc: "添加沙箱化命令可以写入的路径，超出工作目录、会话临时目录以及使用 --add-dir、/add-dir 或 permissions.additionalDirectories 添加的目录。当子进程（如 kubectl 或构建工具）需要在项目外写入时使用它。", scope: "Any file", type: "路径字符串数组，使用 sandbox path prefixes", defaultText: "未设置，因此沙箱化命令可以写入工作目录、会话临时目录、使用 --add-dir 或 /add-dir 添加的目录以及 permissions.additionalDirectories 中的目录", example: "{\n  \"sandbox\": {\n    \"filesystem\": {\n      \"allowWrite\": [\"/tmp/build\", \"~/.kube\"]\n    }\n  }\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "sandbox.filesystem.denyRead", category: "Sandbox 设置", desc: "阻止沙箱化命令读取特定路径，例如默认读取策略会公开的凭证文件。要保护凭证文件并使其可通过沙箱代理使用，请改为参阅 sandbox.credentials。", scope: "Any file", type: "路径字符串数组，使用 sandbox path prefixes", defaultText: "未设置，因此沙箱化命令保持 default read access，包括凭证文件，如 ~/.aws/credentials", example: "{\n  \"sandbox\": {\n    \"filesystem\": {\n      \"denyRead\": [\"~/.aws/credentials\"]\n    }\n  }\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "sandbox.filesystem.denyWrite", category: "Sandbox 设置", desc: "阻止沙箱化命令写入特定路径，包括在其他可写目录内的路径。", scope: "Any file", type: "路径字符串数组，使用 sandbox path prefixes", defaultText: "未设置", example: "{\n  \"sandbox\": {\n    \"filesystem\": {\n      \"denyWrite\": [\"/etc\", \"/usr/local/bin\"]\n    }\n  }\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "sandbox.filesystem.disabled", category: "Sandbox 设置", desc: "跳过文件系统隔离，同时保持网络隔离。沙箱化命令获得对主机文件系统的无限制读写访问，其网络出口仍限制在 network.allowedDomains。当您沙箱化以控制命令连接的位置而不是它们写入的内容时使用它。需要 Claude Code v2.1.216 或更高版本。", scope: "User or managed。当托管设置配置 sandbox.filesystem 时，或列出带有 \"mode\": \"deny\" 的 sandbox.credentials.files 条目时，只有托管设置可以设置它。", type: "布尔值", defaultText: "false，因此文件系统隔离保持打开", example: "{\n  \"sandbox\": {\n    \"enabled\": true,\n    \"filesystem\": {\n      \"disabled\": true\n    },\n    \"network\": {\n      \"allowedDomains\": [\"github.com\", \"*.npmjs.org\"]\n    }\n  }\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "sandbox.ignoreViolations", category: "Sandbox 设置", desc: "沉默沙箱违规报告，针对您期望命令探测并被拒绝的路径，例如在启动时检查 /etc/hosts 的工具，因此这些拒绝不会显示为违规或在 Claude 看到的内容中。沙箱仍然阻止访问；只有报告被抑制。键是与命令匹配的子字符串，* 匹配每个命令，值是该命令要忽略的违规子字符串，例如文件系统路径。", scope: "Any file", type: "对象，将命令子字符串映射到违规子字符串数组，通常是路径", defaultText: "未设置，因此报告每个违规", example: "{\n  \"sandbox\": {\n    \"ignoreViolations\": {\n      \"*\": [\"/etc/hosts\"]\n    }\n  }\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "sandbox.network", category: "Sandbox 设置", desc: "控制沙箱化命令可以到达的主机、端口和套接字。沙箱通过强制执行这些列表的代理路由出站流量；请参阅 Network isolation 了解代理如何决定以及何时提示。", scope: "Any file。strictAllowlist、allowManagedDomainsOnly 和 tlsTerminate 从较少的源读取，如其条目所述。", type: "对象，包含以下子键", defaultText: "未设置，因此没有域被预先允许，沙箱为每个新主机提示", example: "{\n  \"sandbox\": {\n    \"network\": {\n      \"allowedDomains\": [\"github.com\", \"*.npmjs.org\"],\n      \"deniedDomains\": [\"uploads.github.com\"],\n      \"allowLocalBinding\": true\n    }\n  }\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "sandbox.network.allowAllUnixSockets", category: "Sandbox 设置", desc: "让沙箱化命令连接到每个 Unix 套接字。在 Linux 和 WSL2 上，沙箱的 seccomp filter 阻止 socket(AF_UNIX, ...) 调用，因此这是在那里允许 Unix 套接字的唯一方式。当过滤器缺失时，/sandbox 在其 Dependencies 选项卡上报告，沙箱不阻止 Unix 套接字调用。请参阅 Set up Linux and WSL2 了解过滤器来自何处。", scope: "Any file", type: "布尔值", defaultText: "false", example: "{\n  \"sandbox\": {\n    \"network\": {\n      \"allowAllUnixSockets\": true\n    }\n  }\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "sandbox.network.allowLocalBinding", category: "Sandbox 设置", desc: "让 macOS 上的沙箱化命令绑定到 localhost 端口，例如启动开发服务器。", scope: "Any file", type: "布尔值", defaultText: "false", example: "{\n  \"sandbox\": {\n    \"network\": {\n      \"allowLocalBinding\": true\n    }\n  }\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "sandbox.network.allowMachLookup", category: "Sandbox 设置", desc: "列出 macOS 沙箱可能查找的其他 XPC 和 Mach 服务名称。通过 XPC 通信的工具，例如 iOS Simulator 或 Playwright，需要在此处列出其服务。", scope: "Any file", type: "字符串数组，每个是服务名称；单个尾部 * 匹配前缀，\"*\" 单独匹配每个服务", defaultText: "未设置", example: "{\n  \"sandbox\": {\n    \"network\": {\n      \"allowMachLookup\": [\"com.apple.coresimulator.*\"]\n    }\n  }\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "sandbox.network.allowManagedDomainsOnly", category: "Sandbox 设置", desc: "将网络允许列表锁定到托管设置定义的内容。Claude Code 然后仅遵守来自托管设置的 allowedDomains 和 WebFetch(domain:...) 允许规则，忽略来自用户、项目、本地和 --settings 设置的域，并自动阻止非允许的域而不是提示。", scope: "Managed", type: "布尔值", defaultText: "false", example: "{\n  \"sandbox\": {\n    \"network\": {\n      \"allowManagedDomainsOnly\": true,\n      \"allowedDomains\": [\"github.com\", \"*.npmjs.org\"]\n    }\n  }\n}", exampleFile: "managed-settings.json"),
        ClaudeSettingEntry(key: "sandbox.network.allowUnixSockets", category: "Sandbox 设置", desc: "列出 macOS 上沙箱化命令可以连接到的 Unix 套接字路径。Claude Code 在 Linux 和 WSL2 上忽略此列表，其中 seccomp 过滤器无法检查套接字路径；改为在那里使用 allowAllUnixSockets。", scope: "Any file", type: "字符串数组，每个是套接字路径", defaultText: "未设置，因此 macOS 沙箱阻止每个 Unix 套接字", example: "{\n  \"sandbox\": {\n    \"network\": {\n      \"allowUnixSockets\": [\"~/.ssh/agent-socket\"]\n    }\n  }\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "sandbox.network.allowedDomains", category: "Sandbox 设置", desc: "预先允许来自沙箱化命令的出站流量的域，因此沙箱不会为它们提示。通配符（如 *.example.com ）匹配子域，可选的 :port 后缀将条目限制为一个端口；没有端口的条目匹配每个端口。", scope: "Any file。仅当设置 allowManagedDomainsOnly 时的托管设置。", type: "字符串数组，每个是域、通配符模式或 IP 文字，带有可选的 :port 后缀", defaultText: "未设置，因此沙箱在命令首次到达新主机时提示", example: "{\n  \"sandbox\": {\n    \"network\": {\n      \"allowedDomains\": [\"github.com\", \"*.npmjs.org\", \"api.example.com:443\"]\n    }\n  }\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "sandbox.network.deniedDomains", category: "Sandbox 设置", desc: "阻止来自沙箱化命令的出站流量的域，使用与 allowedDomains 相同的通配符、端口和 IPv6 语法。被拒绝的域即使 allowedDomains 条目也匹配它也保持阻止。", scope: "Any file", type: "字符串数组，每个是域、通配符模式或 IP 文字，带有可选的 :port 后缀", defaultText: "未设置", example: "{\n  \"sandbox\": {\n    \"network\": {\n      \"deniedDomains\": [\"sensitive.cloud.example.com\"]\n    }\n  }\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "sandbox.network.httpProxyPort", category: "Sandbox 设置", desc: "将沙箱指向您自己的 HTTP 代理而不是 Claude Code 运行的。组织这样做以检查 HTTPS 流量、应用自己的过滤规则或记录每个请求。未设置时，Claude Code 为 HTTP 流量启动自己的代理。", scope: "Any file", type: "数字，本地 TCP 端口", defaultText: "未设置，因此 Claude Code 运行自己的代理", example: "{\n  \"sandbox\": {\n    \"network\": {\n      \"httpProxyPort\": 8080\n    }\n  }\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "sandbox.network.socksProxyPort", category: "Sandbox 设置", desc: "将沙箱指向您自己的 SOCKS5 代理而不是 Claude Code 运行的。未设置时，Claude Code 为 SOCKS 流量启动自己的代理。", scope: "Any file", type: "数字，本地 TCP 端口", defaultText: "未设置，因此 Claude Code 运行自己的代理", example: "{\n  \"sandbox\": {\n    \"network\": {\n      \"socksProxyPort\": 8081\n    }\n  }\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "sandbox.network.strictAllowlist", category: "Sandbox 设置", desc: "拒绝沙箱化命令访问允许列表外的主机，而不是提示批准。允许列表是 allowedDomains 加上来自 WebFetch(domain:...) 允许规则的域，或仅当设置 allowManagedDomainsOnly 时的托管设置条目。需要 Claude Code v2.1.219 或更高版本。", scope: "User or managed。存储库无法打开或关闭它。", type: "布尔值", defaultText: "false", example: "{\n  \"sandbox\": {\n    \"network\": {\n      \"strictAllowlist\": true\n    }\n  }\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "sandbox.network.tlsTerminate", category: "Sandbox 设置", desc: "使沙箱代理终止 TLS，以便它可以读取 HTTPS 请求的内容。这是实验性的，mask credential substitution 需要它。设置 {} 为会话生成临时证书颁发机构，或设置 caCertPath 和 caKeyPath 以使用您自己的。", scope: "User or managed。存储库无法打开它或提供证书颁发机构。", type: "对象，包含可选的 caCertPath 和 caKeyPath 字符串，每个是文件路径", defaultText: "未设置，因此代理不终止或检查 TLS", example: "{\n  \"sandbox\": {\n    \"network\": {\n      \"tlsTerminate\": {}\n    }\n  }\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "sandbox.ripgrep", category: "Sandbox 设置", desc: "将沙箱指向您自己的 ripgrep 二进制文件，而不是 Claude Code 使用的，例如当您的平台需要不同构建的 rg 时。", scope: "User or managed", type: "对象，包含 command（ripgrep 二进制文件的路径）和可选的 args（要前置的参数数组）", defaultText: "未设置，因此沙箱使用与 Claude Code 相同的 ripgrep 二进制文件。这是捆绑的二进制文件，除非您将 USE_BUILTIN_RIPGREP 设置为 0", example: "{\n  \"sandbox\": {\n    \"ripgrep\": {\n      \"command\": \"/usr/local/bin/rg\"\n    }\n  }\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "sandbox.socatPath", category: "Sandbox 设置", desc: "将沙箱网络代理指向安装在 PATH 外的 socat 二进制文件。", scope: "Managed", type: "字符串，绝对路径；Claude Code 删除相对路径并回退到 PATH 查找", defaultText: "未设置，因此 Claude Code 在 PATH 上找到 socat", example: "{\n  \"sandbox\": {\n    \"enabled\": true,\n    \"socatPath\": \"/opt/admin/socat\"\n  }\n}", exampleFile: "managed-settings.json"),
        ClaudeSettingEntry(key: "showClearContextOnPlanAccept", category: "界面和终端", desc: "当 Claude 在计划模式中完成计划时，它显示一个批准菜单。规划可能会使用大量上下文，因此此键向该菜单添加第一个选项**是的，清除上下文并…**，它批准计划、清除对话上下文并仅从计划开始实施。标签的其余部分命名会话继续的权限模式，并显示规划使用了多少上下文。", scope: "Any file", type: "Boolean", defaultText: "false", example: "{\n  \"showClearContextOnPlanAccept\": true\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "showThinkingSummaries", category: "模型和响应", desc: "在交互式会话中查看 Claude 的扩展思考摘要。如果您想在使用 Ctrl+O 展开思考时看到完整摘要，请设置它。未设置或 false 时，Anthropic API 编辑思考块，Claude Code 显示折叠的存根；第三方提供商不编辑。", scope: "Any file", type: "Boolean", defaultText: "false", example: "{\n  \"showThinkingSummaries\": true\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "showTurnDuration", category: "界面和终端", desc: "显示或隐藏每个响应后的转向持续时间消息，如\"Cooked for 1m 6s · done 6:05 PM\"。\"done\"后的时钟显示转向何时完成；timeFormat 和 timeZone 控制其格式和区域。在 /config 中显示为**显示转向持续时间**。", scope: "Any file。当没有设置文件设置它时，来自较旧版本的 ~/.claude.json 中的值适用。", type: "Boolean", defaultText: "true", example: "{\n  \"showTurnDuration\": false\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "skillListingBudgetFraction", category: "内存和上下文", desc: "每个回合，Claude 看到您的技能列表及其描述，Claude Code 将该列表限制在上下文窗口的一部分。当列表超过上限时，Claude Code 保留每个技能的名称，但删除使用最少的技能的描述，因此 Claude 仍然可以调用这些技能，但不太可能自己选择一个。提高此键以保持更多描述可见，代价是每个回合更多上下文。", scope: "Any file", type: "数字，大于 0 且最多 1 的分数", defaultText: "0.01，保留 1% 的上下文窗口", example: "{\n  \"skillListingBudgetFraction\": 0.02\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "skillListingMaxDescChars", category: "内存和上下文", desc: "每个回合，Claude 看到您的技能列表，显示每个技能的 description 和 when_to_use 文本。此键限制 Claude Code 每个技能显示多少字符的该文本；较长的文本在上限处被切割。", scope: "Any file", type: "字符数，正整数", defaultText: "1536", example: "{\n  \"skillListingMaxDescChars\": 2048\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "skillOverrides", category: "插件和技能", desc: "隐藏或折叠 skill，无需编辑其 SKILL.md。Claude Code 将每个技能名称下的值应用于 Claude 看到的技能列表和您的 / 自动完成。", scope: "Any file。/skills 菜单写入 .claude/settings.local.json。", type: "对象，将技能名称映射到以下之一：", defaultText: "未设置，因此每个技能都是 \"on\"", example: "{\n  \"skillOverrides\": {\n    \"legacy-context\": \"name-only\",\n    \"deploy\": \"off\"\n  }\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "skipAutoPermissionPrompt", category: "权限设置", desc: "跳过 Claude Code 在您自己首次进入自动模式时显示的一次性通知，描述自动模式，例如通过您自己的设置或模式选择器，而不是当内置默认值在其中启动会话时。Claude Code 显示该通知一次，然后记录它已显示，因此此键仅在通知尚未出现的地方重要。", scope: "User or managed。存储库无法为您设置它。", type: "布尔值", defaultText: "未设置，因此通知出现一次", example: "{\n  \"skipAutoPermissionPrompt\": true\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "skipDangerousModePermissionPrompt", category: "权限设置", desc: "跳过 Claude Code 在会话进入 bypassPermissions 模式之前显示的确认对话框，无论是来自 --dangerously-skip-permissions 还是来自 defaultMode: \"bypassPermissions\"。当您接受该对话框一次时，Claude Code 在您的用户设置中写入 true。", scope: "User, local, or managed。不受信任的存储库无法为您跳过对话框。", type: "布尔值", defaultText: "未设置，因此对话框出现", example: "{\n  \"skipDangerousModePermissionPrompt\": true\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "skipWebFetchPreflight", category: "隐私和遥测", desc: "跳过 WebFetch 域安全检查，该检查在获取之前将每个请求的主机名发送到 api.anthropic.com。在阻止到 Anthropic 的流量的环境中设置 true，例如 Amazon Bedrock、Google Cloud 的 Agent Platform 或具有限制性出站的 Microsoft Foundry 部署。", scope: "任何文件", type: "布尔值", defaultText: "未设置，因此检查在会话中首次获取每个主机名之前运行", example: "{\n  \"skipWebFetchPreflight\": true\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "spellcheck", category: "界面和终端", desc: "在您键入时在提示输入中为拼写错误的单词加下划线，使用您安装的拼写检查器。Claude Code 仅检查输入框中的文本。在您键入时检查拼写涵盖安装 aspell、hunspell 或 ispell 以及检查器涵盖的内容。需要 Claude Code v2.1.235 或更高版本。", scope: "User or managed。设置它的最高层的块整体应用。", type: "对象，包含 enabled（Boolean）、checker（\"aspell\"、\"hunspell\"、\"ispell\" 或 \"auto\"）、language（字符串，传递给检查器作为其字典名称）和 color（字符串，终端颜色名称、#rrggbb、rgb(r,g,b)、ansi256(n) 或 ansi:<name>）", defaultText: "unset，所以拼写检查关闭；checker 默认为 \"auto\"，PATH 上找到的前三个之一；language 默认为检查器自己的字典；color 默认为主题的错误颜色", example: "{\n  \"spellcheck\": { \"enabled\": true, \"language\": \"en_GB\" }\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "spinnerTipsEnabled", category: "界面和终端", desc: "当 Claude 工作时，加载动画行轮换显示关于 Claude Code 功能的短提示，如\"使用计划模式为复杂请求做准备，然后再进行更改。按 Shift+Tab 两次以启用。\"将此键设置为 false 以隐藏它们。在 /config 中显示为**显示提示**。", scope: "Any file", type: "Boolean", defaultText: "true", example: "{\n  \"spinnerTipsEnabled\": false\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "spinnerTipsOverride", category: "界面和终端", desc: "将您自己的提示添加到 Claude Code 在 Claude 工作时显示的加载动画提示，或用您的提示替换内置提示。Claude Code 将您的提示放在与内置提示相同的轮换中：它选择未显示时间最长的提示，跳过仍在冷却期中的提示，并通过优先级打破平局。 如果您将 spinnerTipsEnabled 设置为 false，Claude Code 会隐藏所有提示，包括您的。", scope: "Any file。Claude Code 从用户设置、--settings 标志和托管设置中尊重提示对象、tipsFile、label 和 excludeDefault；从项目和本地设置中，它仅读取纯字符串提示。", type: "对象，包含 tips、tipsFile、label 和 excludeDefault 字段，每个都是可选的", defaultText: "unset，所以 Claude Code 仅显示内置提示", example: "{\n  \"spinnerTipsOverride\": {\n    \"label\": \"Acme tip\",\n    \"tips\": [\n      \"在打开 PR 之前运行 /review\",\n      {\n        \"id\": \"gateway-errors\",\n        \"text\": \"看到 5xx 错误？首先检查网关状态页面\",\n        \"cooldownSessions\": 5,\n        \"priority\": 2\n      }\n    ]\n  }\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "spinnerVerbs", category: "界面和终端", desc: "当转向进行中时，加载动画显示轮换的动词，如\"Accomplishing\"、\"Architecting\"或\"Baking\"。使用此键将您自己的动词添加到该轮换或用您的替换内置列表。", scope: "Any file", type: "对象，包含 verbs 字符串数组和 mode，值为以下之一：", defaultText: "unset，所以 Claude Code 使用内置动词", example: "{\n  \"spinnerVerbs\": {\n    \"mode\": \"append\",\n    \"verbs\": [\"Pondering\", \"Crafting\"]\n  }\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "sshConfigs", category: "远程、桌面和通知", desc: "将 SSH 连接添加到桌面环境下拉列表。管理员使用它向团队分发共享连接。你在托管设置中定义的连接显示为托管，因此用户可以选择它们，但无法在应用中编辑或删除它们。", scope: "用户或托管。桌面应用读取此键。", type: "对象数组，每个都有必需的 id、name 和 sshHost 以及可选的 sshPort 和 sshIdentityFile", defaultText: "未设置", example: "{\n  \"sshConfigs\": [\n    {\n      \"id\": \"dev-vm\",\n      \"name\": \"Dev VM\",\n      \"sshHost\": \"user@dev.example.com\"\n    }\n  ]\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "sshHostAllowlist", category: "远程、桌面和通知", desc: "限制桌面 SSH 会话可以连接到的主机。仅桌面应用读取此键；CLI 不读取。模式不区分大小写：* 匹配任何主机，*.example.com 匹配 example.com 和每个子域，其他任何内容都是针对 ~/.ssh/config 解析后的主机名的精确匹配。空数组关闭 SSH 会话。", scope: "托管", type: "主机名模式数组", defaultText: "未设置，因此允许任何主机", example: "{\n  \"sshHostAllowlist\": [\"*.devboxes.example.com\", \"bastion.example.com\"]\n}", exampleFile: "managed-settings.json"),
        ClaudeSettingEntry(key: "statusLine", category: "界面和终端", desc: "运行您自己的命令来渲染提示下方的状态行，包含模型、成本或 git 分支等上下文。可选字段调整间距、添加定期重新运行，并在您的脚本自己渲染 vim.mode 时隐藏内置 vim 模式指示器。", scope: "Any file。当 allowManagedHooksOnly 打开时，或 disableAllHooks 在托管设置外设置时，仅托管设置值运行。", type: "对象，type 设置为 \"command\" 和 command 字符串，加上可选的 padding 作为字符数、refreshInterval 作为秒数（最少 1）和 hideVimModeIndicator 作为 Boolean", defaultText: "unset，所以没有状态行", example: "{\n  \"statusLine\": {\n    \"type\": \"command\",\n    \"command\": \"jq -r '\\\"[\\\\(.model.display_name)] \\\\(.context_window.used_percentage // 0)% context\\\"'\",\n    \"padding\": 2\n  }\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "strictKnownMarketplaces", category: "插件和技能", desc: "限制您组织中的人员可以添加和安装插件的插件市场来源。Claude Code 在市场添加以及插件安装、更新、刷新和自动更新时强制执行允许列表，在任何网络或文件系统操作之前，因此在您设置策略之前添加的市场一旦其来源不再匹配就无法用于获取插件。被阻止的用户会看到一个错误，命名托管策略。", scope: "Managed", type: "市场来源对象数组；请参阅 允许的来源类型", defaultText: "未设置，因此用户可以添加任何市场。空数组是完全锁定，阻止每个市场来源，包括官方 Anthropic 市场", example: "{\n  \"strictKnownMarketplaces\": [\n    { \"source\": \"github\", \"repo\": \"acme-corp/approved-plugins\" },\n    { \"source\": \"github\", \"repo\": \"acme-corp/security-tools\", \"ref\": \"v2.0\" },\n    { \"source\": \"url\", \"url\": \"https://plugins.example.com/marketplace.json\" }\n  ]\n}", exampleFile: "managed-settings.json"),
        ClaudeSettingEntry(key: "strictPluginOnlyCustomization", category: "插件和技能", desc: "阻止来自用户和项目来源的技能、代理、hooks 和 MCP 服务器，因此它们只能来自插件或托管设置。将其与 strictKnownMarketplaces 结合以控制完整的自定义供应链：市场允许列表控制用户可以安装哪些插件。", scope: "Managed", type: "true 以锁定所有四种自定义，或命名要锁定的种类的数组，来自 \"skills\"、\"agents\"、\"hooks\" 和 \"mcp\"", defaultText: "未设置，因此没有锁定", example: "{\n  \"strictPluginOnlyCustomization\": [\"skills\", \"hooks\"]\n}", exampleFile: "managed-settings.json"),
        ClaudeSettingEntry(key: "strictPluginOnlyCustomization.agents", category: "插件和技能", desc: "锁定 agents 表面。Claude Code 停止从 ~/.claude/agents/ 和 .claude/agents/ 加载代理，并继续加载插件代理、内置代理和托管策略目录中的代理。", scope: "Managed", type: "strictPluginOnlyCustomization 数组中的字符串 \"agents\"", defaultText: "未锁定", example: "{\n  \"strictPluginOnlyCustomization\": [\"agents\"]\n}", exampleFile: "managed-settings.json"),
        ClaudeSettingEntry(key: "strictPluginOnlyCustomization.hooks", category: "插件和技能", desc: "锁定 hooks 表面。Claude Code 停止运行来自用户、项目和本地 settings.json 的 hooks，并继续运行插件 hooks 和托管设置中的 hooks。", scope: "Managed", type: "strictPluginOnlyCustomization 数组中的字符串 \"hooks\"", defaultText: "未锁定", example: "{\n  \"strictPluginOnlyCustomization\": [\"hooks\"]\n}", exampleFile: "managed-settings.json"),
        ClaudeSettingEntry(key: "strictPluginOnlyCustomization.mcp", category: "插件和技能", desc: "锁定 mcp 表面。Claude Code 停止从 ~/.claude.json 和 .mcp.json 加载 MCP 服务器，并继续加载插件 MCP 服务器、managed-mcp.json 服务器和来自 managedMcpServers 的服务器。", scope: "Managed", type: "strictPluginOnlyCustomization 数组中的字符串 \"mcp\"", defaultText: "未锁定", example: "{\n  \"strictPluginOnlyCustomization\": [\"mcp\"]\n}", exampleFile: "managed-settings.json"),
        ClaudeSettingEntry(key: "strictPluginOnlyCustomization.skills", category: "插件和技能", desc: "锁定 skills 表面。Claude Code 停止从 ~/.claude/skills/ 和 .claude/skills/、~/.claude/commands/ 和 .claude/commands/ 中的自定义命令、--add-dir 目录下的技能以及从您的 claude.ai 帐户同步的技能加载技能，并继续加载插件技能、捆绑技能和托管策略目录中的技能。", scope: "Managed", type: "strictPluginOnlyCustomization 数组中的字符串 \"skills\"", defaultText: "未锁定", example: "{\n  \"strictPluginOnlyCustomization\": [\"skills\"]\n}", exampleFile: "managed-settings.json"),
        ClaudeSettingEntry(key: "subagentPromptCacheTtl", category: "模型和响应", desc: "选择提示缓存保持 Claude Code 在主对话外进行的请求的时间长度。此键适用于subagent、工作流和 Claude Code 自己的后台和助手请求，例如压缩和会话标题。一小时的生命周期在较长的中断中保持缓存温暖，API 以比五分钟生命周期更高的费率为每个缓存写入计费。需要 Claude Code v2.1.242 或更高版本。", scope: "Any file", type: "string，其中之一：", defaultText: "未设置，因此这些请求中的每一个都获得其默认生命周期", example: "{\n  \"subagentPromptCacheTtl\": \"1h\"\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "subagentStatusLine", category: "界面和终端", desc: "当 Claude 运行子代理时，Claude Code 在提示下方的任务显示中列出它们，每个子代理一行显示 name · description · token count。此键让您运行自己的命令来重写这些行，例如显示每个子代理的上下文使用情况百分比。在每次刷新时，Claude Code 将可见行作为一个 JSON 对象发送到 stdin，其中 tasks 数组包含每个子代理的 id、name、status、model、tokenCount 等，并将您写回的每个 id 的行替换为 {\"id\", \"content\"} 行。您不写回的行保持默认渲染。", scope: "Any file。当 allowManagedHooksOnly 打开时，或 disableAllHooks 在托管设置外设置时，仅托管设置值运行。", type: "对象，type 设置为 \"command\" 和 command 字符串", defaultText: "unset，所以 Claude Code 渲染默认行", example: "{\n  \"subagentStatusLine\": {\n    \"type\": \"command\",\n    \"command\": \"jq -c '.tasks[] | {id, content: \\\"\\\\(.name): \\\\(.tokenCount) tokens\\\"}'\"\n  }\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "switchModelsOnFlag", category: "模型和响应", desc: "选择当安全分类器标记请求时会发生什么：切换到备用模型并继续，或暂停以便您可以在切换和编辑提示之间选择。", scope: "Any file。在 /config 中显示为**消息被标记时切换模型**。", type: "Boolean", defaultText: "true，自动切换", example: "{\n  \"switchModelsOnFlag\": false\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "syncClaudeAiPlugins", category: "插件和技能", desc: "关闭 您在 claude.ai 上启用的插件 的下载。Claude Code 在您使用 claude.ai 帐户登录的终端会话开始时将它们下载到 ~/.claude/plugins/synced/，以及在 Cowork 和云会话中，并将每个加载为 <name>@synced。设置为 false 以停止该下载并停止加载已同步的插件。Claude Code 仅接受 false：true 与未设置相同，不会打开同步。需要 Claude Code v2.1.273 或更高版本。", scope: "User, local, or managed，以及使用 --settings 传递的文件。存储库无法为您关闭它。", type: "Boolean", defaultText: "未设置，因此使用 claude.ai 帐户登录的会话会同步您的插件", example: "{\n  \"syncClaudeAiPlugins\": false\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "syncClaudeAiSkills", category: "插件和技能", desc: "关闭 您在 claude.ai 上启用的技能 的下载。Claude Code 在 您使用 claude.ai 帐户登录的终端会话（交互式或非交互式）以及 Cowork 和云会话中将它们下载到 ~/.claude/skills/synced/。设置为 false 以停止该下载并停止加载已同步的技能。Claude Code 仅接受 false：true 与未设置相同，不会打开同步。", scope: "User, local, or managed，以及使用 --settings 传递的文件。存储库无法为您关闭它。", type: "Boolean", defaultText: "未设置，因此使用 claude.ai 帐户登录的会话会同步您的技能", example: "{\n  \"syncClaudeAiSkills\": false\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "syntaxHighlightingDisabled", category: "界面和终端", desc: "Claude Code 使用其内置高亮器按语言为它在终端中显示的差异、代码块和文件预览着色；不涉及插件或语言服务器。将此键设置为 true 以改为将它们显示为纯文本，例如如果颜色与您的终端主题冲突或减慢屏幕阅读器。", scope: "Any file", type: "Boolean", defaultText: "false", example: "{\n  \"syntaxHighlightingDisabled\": true\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "taskOutputMaxChars", category: "内存和上下文", desc: "<Warning> 在 v2.1.277 中删除，连同它调整大小的 TaskOutput 工具一起。设置它对当前版本没有影响。Claude 使用 Read 读取后台任务的输出文件。 </Warning> 通过 v2.1.276，您将此键设置为后台任务的输出字符数，当 Claude 使用 TaskOutput 工具读取任务时 Claude 内联接收。 改变 Claude Code 在终端中的外观和行为：主题、编辑器模式、状态行、加载动画、会话内通知和无障碍功能。请参阅终端配置。", scope: "", type: "", defaultText: "", example: "", exampleFile: ""),
        ClaudeSettingEntry(key: "teammateDefaultModel", category: "全局配置设置", desc: "<Warning> 在 v2.1.234 中删除，以及其 /config 行**默认队友模型**。在当前版本中设置它没有效果。 </Warning> 在 v2.1.233 及更早版本中，你将此键设置为代理团队队友的模型，你的提示没有为其命名模型：一个别名如 \"sonnet\"，或 null 以遵循主导的模型。有关 Claude Code 现在为此类队友选择的模型，请参阅指定队友和模型。", scope: "全局配置。在 v2.1.233 及更早版本上。", type: "字符串，模型别名或完整模型 ID，或 null", defaultText: "未设置", example: "", exampleFile: ""),
        ClaudeSettingEntry(key: "teammateMode", category: "代理、会话和工作树", desc: "选择 Claude Code 显示 agent team 队友的位置：在您的主终端窗格内，或在您的终端支持时在分割窗格中。请参阅 Choose a display mode。", scope: "Any file。Claude Code 也读取由较旧版本留在 ~/.claude.json 中的值。", type: "string，以下之一：", defaultText: "\"in-process\"", example: "{\n  \"teammateMode\": \"auto\"\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "terminalProgressBarEnabled", category: "界面和终端", desc: "某些终端可以在选项卡或任务栏中为在其中运行的程序显示进度指示器。当 Claude 工作时，Claude Code 向终端报告进行中状态，因此您可以从另一个选项卡或窗口看到会话是否仍然繁忙。指示器在转向结束后保持可见，同时后台子代理或动态工作流仍在运行，并在会话空闲后清除。 Claude Code 仅在支持指示器的终端中报告它：ConEmu、Ghostty 1.2.0 或更高版本以及 iTerm2 3.6.6 或更高版本。将此键设置为 false 以停止 Claude Code 报告它。在 /config 中显示为**终端进度条**。", scope: "Any file。当没有设置文件设置它时，来自较旧版本的 ~/.claude.json 中的值适用。", type: "Boolean", defaultText: "true", example: "{\n  \"terminalProgressBarEnabled\": false\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "terminalTitleFromRename", category: "界面和终端", desc: "Claude Code 设置您的终端选项卡的标题。默认情况下，它使用从对话生成的标题，一旦您使用 /rename 或 --name 给会话命名，选项卡会改为显示该名称。将此键设置为 false 以在您命名会话后保持生成的标题在选项卡上。名称本身仍然适用，因此 /resume <name> 和会话选择器找到它。", scope: "Any file", type: "Boolean", defaultText: "true", example: "{\n  \"terminalTitleFromRename\": false\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "theme", category: "界面和终端", desc: "为界面选择颜色主题。在 /config 中显示为**主题**。", scope: "Any file。当没有设置文件设置它时，来自较旧版本的 ~/.claude.json 中的值适用。", type: "string，值为以下之一：", defaultText: "\"dark\"", example: "{\n  \"theme\": \"light-daltonized\"\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "timeFormat", category: "界面和终端", desc: "选择 Claude Code 如何写入它在界面中显示的时间，如每个转向持续时间消息末尾的 done 6:05 PM 和记录查看器中的时间戳。要选择预设，运行 /config 并设置**时间格式**。需要 Claude Code v2.1.257 或更高版本。", scope: "Any file", type: "string，值为以下之一：", defaultText: "\"auto\"", example: "{\n  \"timeFormat\": \"24-hour\"\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "timeZone", category: "界面和终端", desc: "在不同于您系统的时区中显示界面中的时间。将其设置为 IANA 时区名称，如 \"UTC\" 或 \"Europe/Dublin\"。timeFormat 控制的时间然后在此区域中显示。如果 timeFormat 是 \"24-hour-utc\"，时间保持在 UTC 中，Claude Code 忽略此键。/config 对此键没有行，因此在设置文件中设置它。需要 Claude Code v2.1.257 或更高版本。", scope: "Any file", type: "string，IANA 时区名称。当 Claude Code 不识别名称时，它使用您的系统时区", defaultText: "unset，所以时间显示在您的系统时区", example: "{\n  \"timeZone\": \"Europe/Dublin\"\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "tui", category: "界面和终端", desc: "选择终端 UI 渲染器。使用 \"fullscreen\" 获得无闪烁的替代屏幕渲染器，具有虚拟化滚动条，或使用 \"default\" 获得经典主屏幕渲染器。运行 /tui fullscreen 或 /tui default 为您写入此键。", scope: "Any file", type: "string，值为以下之一：", defaultText: "unset，所以 Claude Code 为您选择渲染器", example: "{\n  \"tui\": \"fullscreen\"\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "ultracode", category: "模型和响应", desc: "使用ultracode启动会话。启用它后，Claude 为每个实质性任务规划工作流，而不是等待您要求。Claude 仅在为您启用动态工作流、您的模型支持 xhigh 努力且没有努力上限低于 xhigh 时规划工作流。无论如何，ultracode: true 在 xhigh 努力或当努力上限较低时在上限处运行会话。Claude Code 读取此键但从不写入它：/effort ultracode 仅为当前会话打开 ultracode。", scope: "Any file", type: "Boolean", defaultText: "未设置，因此 ultracode 已关闭", example: "{\n  \"ultracode\": true\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "useAutoModeDuringPlan", category: "权限设置", desc: "选择 Claude Code 是否使用自动模式分类器在计划模式下审查 shell 命令。使用默认值 true，分类器在规划期间审查每个命令，当自动模式可用且您看不到提示时。设置 false 以获得内置只读集之外的每个命令的权限提示。在 /config 中显示为**在计划期间使用自动模式**。", scope: "User, local, or managed。存储库无法为您关闭它。", type: "布尔值", defaultText: "true", example: "{\n  \"useAutoModeDuringPlan\": false\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "verbose", category: "界面和终端", desc: "默认情况下，记录将每个工具调用折叠为简短摘要，如 Claude 运行的命令和其输出的行数，您按 Ctrl+O 在需要详细信息时将整个记录切换到展开视图。将此键设置为 true 以在发生时内联显示每个工具调用的完整输入和输出，这在您调试 hook、MCP 服务器或长 shell 命令时很有用。在 /config 中显示为**详细输出**。", scope: "Any file。当没有设置文件设置它时，来自较旧版本的 ~/.claude.json 中的值适用。", type: "Boolean", defaultText: "false", example: "{\n  \"verbose\": true\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "viewMode", category: "界面和终端", desc: "设置 Claude Code 启动的记录视图：\"default\"、\"verbose\" 或 \"focus\"。设置时，它覆盖粘性 /focus 选择和 verbose 设置。", scope: "Any file", type: "string，值为以下之一：", defaultText: "unset，所以 verbose 设置和您最后的 /focus 选择适用", example: "{\n  \"viewMode\": \"focus\"\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "vimInsertModeRemaps", category: "界面和终端", desc: "在 vim 编辑器模式中将两键 INSERT 模式序列映射到 Escape。每个键恰好是按顺序键入的两个可打印字符，\"<Esc>\" 是唯一支持的目标；Claude Code 忽略其他条目。需要 Claude Code v2.1.208 或更高版本。", scope: "User or managed。存储库不能重新映射您的按键。", type: "对象，将两字符序列映射到 \"<Esc>\"", defaultText: "unset", example: "{\n  \"vimInsertModeRemaps\": {\n    \"jj\": \"<Esc>\"\n  }\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "voice", category: "界面和终端", desc: "打开语音听写并选择听写键的行为方式。当您运行 /voice 时，Claude Code 为您写入此对象。", scope: "Any file", type: "对象，enabled 作为 Boolean，autoSubmit 作为仅在保持模式中适用的 Boolean，和 mode，值为以下之一：", defaultText: "unset，所以听写关闭；当 enabled 是 true 且 mode 未设置时，Claude Code 使用 \"hold\"", example: "{\n  \"voice\": {\n    \"enabled\": true,\n    \"mode\": \"tap\"\n  }\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "voiceEnabled", category: "界面和终端", desc: "<Warning> 自 v2.1.92 起已弃用，当 voice 对象替换它时。Claude Code 仍然读取它，因此较旧的设置文件保持工作，但新配置应设置 voice.enabled。 </Warning> 使用在 voice 对象之前的单个 Boolean 形式打开语音听写。当两者都设置时，voice.enabled 适用。", scope: "Any file", type: "Boolean", defaultText: "unset", example: "{\n  \"voiceEnabled\": true\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "wheelScrollAccelerationEnabled", category: "界面和终端", desc: "在全屏渲染中快速滚动期间加速鼠标滚轮滚动速度。将其设置为 false 以获得每个滚轮凹口的恒定滚动速率。", scope: "Any file", type: "Boolean", defaultText: "true", example: "{\n  \"wheelScrollAccelerationEnabled\": false\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "workflowKeywordTriggerEnabled", category: "Hooks 和自动化", desc: "选择在提示中键入关键字 ultracode 是否触发 动态工作流。将其设置为 false 以在不触发工作流的情况下键入该词。", scope: "任何文件。在 /config 中显示为 **Ultracode 关键字触发**。", type: "布尔值", defaultText: "true", example: "{\n  \"workflowKeywordTriggerEnabled\": false\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "workflowSizeGuideline", category: "Hooks 和自动化", desc: "设置 Claude 在其编写的动态工作流中针对的代理计数。Claude Code 将值作为建议而不是强制上限发送给 Claude：\"small\" 要求少于 5 个代理，\"medium\" 少于 10 个，\"large\" 少于 50 个。当您想限制工作流花费的内容时，选择 \"small\"。需要 Claude Code v2.1.219 或更高版本。", scope: "任何文件。那里的值优先于 /config 中的 **动态工作流大小** 选择，Claude Code 将其存储在 ~/.claude.json 中，当设置文件设置键时，Claude Code 隐藏该行。", type: "字符串，以下之一：", defaultText: "\"medium\"，或 当您在 Pro 计划上使用 Claude Code v2.1.271 或更高版本登录时为 \"small\"", example: "{\n  \"workflowSizeGuideline\": \"small\"\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "worktree", category: "代理、会话和工作树", desc: "配置 Claude Code 如何为 --worktree、EnterWorktree 工具以及隔离的 subagents 和后台会话创建和管理 git worktrees。", scope: "Any file", type: "object with baseRef, symlinkDirectories, sparsePaths, and bgIsolation", defaultText: "未设置", example: "{\n  \"worktree\": {\n    \"baseRef\": \"head\",\n    \"symlinkDirectories\": [\"node_modules\"]\n  }\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "worktree.baseRef", category: "代理、会话和工作树", desc: "选择新工作树从哪个 ref 分支。\"fresh\" 从 origin/<default-branch> 分支以获得与远程匹配的干净树；\"head\" 从您当前的本地 HEAD 分支，因此未推送的提交和功能分支状态存在于工作树中。", scope: "Any file", type: "string，以下之一：", defaultText: "\"fresh\"", example: "{\n  \"worktree\": {\n    \"baseRef\": \"head\"\n  }\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "worktree.bgIsolation", category: "代理、会话和工作树", desc: "选择 background sessions 如何隔离其文件编辑。使用 \"worktree\"，Claude Code 在会话调用 EnterWorktree 之前阻止主检出中的 Edit 和 Write；使用 \"none\"，后台作业直接编辑工作副本。对于 git worktrees 不切实际的存储库，设置 \"none\"。", scope: "Any file", type: "string，以下之一：", defaultText: "\"worktree\"", example: "{\n  \"worktree\": {\n    \"bgIsolation\": \"none\"\n  }\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "worktree.sparsePaths", category: "代理、会话和工作树", desc: "通过 git sparse-checkout 在每个工作树中仅检出列出的目录。Claude Code 仅将这些目录加上根级文件写入磁盘，这在大型 monorepos 中更快；请参阅 Check out only the directories you need。", scope: "Any file", type: "array of strings，相对于存储库根目录的目录路径", defaultText: "未设置，因此每个工作树检出整个树", example: "{\n  \"worktree\": {\n    \"sparsePaths\": [\"packages/my-app\", \"shared/utils\"]\n  }\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "worktree.symlinkDirectories", category: "代理、会话和工作树", desc: "将目录从主存储库符号链接到每个工作树中，以便您不会在磁盘上复制大型目录。", scope: "Any file", type: "array of strings，相对于存储库根目录的目录路径", defaultText: "未设置，因此 Claude Code 不符号链接任何目录", example: "{\n  \"worktree\": {\n    \"symlinkDirectories\": [\"node_modules\", \".cache\"]\n  }\n}", exampleFile: "settings.json"),
        ClaudeSettingEntry(key: "wslInheritsWindowsSettings", category: "企业和托管设置", desc: "让 WSL 上的 Claude Code 从 Windows 策略链读取托管设置，HKLM 和 Windows 托管设置文件优先于 /etc/claude-code 和下面的 HKCU。当链打开时，Claude Code 仅在 C:\\Program Files\\ClaudeCode\\ 下没有托管设置文件或删除项提供策略密钥时才读取 /etc/claude-code。设置它以将您已在 Windows 上部署的策略扩展到同一机器上的 WSL 会话，以便它们遵循与主机会话相同的规则。Claude Code 仅在 HKLM 注册表密钥或 C:\\Program Files\\ClaudeCode\\ 下的托管设置文件或删除项中设置时才接受它，两者都需要 Windows 管理员写入。", scope: "Managed。在管理员控制的 Windows 源中。", type: "Boolean", defaultText: "false，因此 WSL 仅读取 /etc/claude-code", example: "{\n  \"wslInheritsWindowsSettings\": true\n}", exampleFile: "managed-settings.json"),
    ]
}
